//! Transaction validation logic
//!
//! This is the core validation that runs inside zkVM.
//! Order of checks is NORMATIVE (see Yellow Paper Section 26):
//! 1. State ID check (BEFORE epoch check)
//! 2. wallet_seq check
//! 3. Receiver wallet_id check
//! 4. Client signature
//! 5. Balance check
//! 6. Conservation law

// CONSENSUS_CRITICAL

