/// Maximum number of unresolved scars (no nabla_confirmation AND no burn_proof)
/// a wallet may carry before new transactions are rejected.
/// Prevents unbounded scar accumulation from repeated double-spend attempts.
pub const MAX_UNRESOLVED_SCARS: usize = protocol_gen::MAX_UNRESOLVED_SCARS as usize;

// Protocol constants from protocol_core.toml (generated by build.rs)
#[allow(dead_code)]
pub(crate) mod protocol_gen {
    include!(concat!(env!("OUT_DIR"), "/protocol_constants.rs"));
}

/// Minimum transaction amount in atoms (anti-spam dust floor).
/// Core's own protocol POLICY — single source: protocol_core.toml `minimum_tx_atoms`
/// (a threshold Core enforces, not a denomination unit). Enforced per YPX-002 §10.2 (G2).
pub const MINIMUM_TX_ATOMS: u64 = protocol_gen::MINIMUM_TX_ATOMS;

/// Atoms per AXC (denomination constant).
/// Single source: `axiom_denomination` (which reads protocol_denomination.toml at build).
pub const ATOMS_PER_AXC: u64 = axiom_denomination::ATOMS_PER_AXC;

// `OWNER_PROOF_REQUIRED_EPOCH` (register `owner_proof_required_epoch`) DELETED
// 2026-09-25 with `Transaction.owner_proof` (KI#108). It gated nothing: the
// step-3.5 "policy gate" it named was a `let _ = wallet;` no-op.

/// Maximum DWP votes per sender per case per tick.
pub const MAX_VOTES_PER_CASE_PER_TICK: u64 = protocol_gen::MAX_VOTES_PER_CASE_PER_TICK;

/// Genesis lockup duration in seconds (3 years = 94,608,000 seconds).
/// Lockup start is GENESIS_STAKE_LOCK_START_SECS (genesis_integrity.rs) —
/// decoupled 2026-09-20 from the news anchor, which is proof-of-fair-launch
/// only. tx.epoch is compared as a unix timestamp.
pub const GENESIS_LOCKUP_SECONDS: u64 = protocol_gen::LOCKUP_SECONDS;

/// ── VBC lifecycle windows (AXIOM_DESIGN_ValidatorJoin.md §5.2) ──
///
/// All three are tick VALUE SPANS in seconds (YPX-003 §1.3.3a), compared
/// against `expires_at - tick` which is also a value span. NOT event counts;
/// those differ by TICK_INTERVAL_SECS (5x) — the confusion behind KI#131.
///
/// The `now` argument is unix seconds. Sourcing it from an ATTESTED TARDIS
/// tick — a witnessed artifact a validator cannot manufacture — is deferred
/// (KI#130); today's callers pass wall-clock-derived time, so a node's own
/// clock influences the verdict. Bounded by `expires_at` living inside the
/// issuer-signed certificate, and by renewal requiring three independent
/// issuers to agree.
/// Below this much remaining life, a VBC can no longer serve.
pub const VBC_UNUSABLE_REMAINING_SECS: u64 = protocol_gen::VBC_UNUSABLE_REMAINING_SECS;

/// §5.3 — how much life an issuer's OWN certificate must have left before it
/// may admit a new validator. SEPARATE from the serving bar above on purpose:
/// "may you witness" and "may you let someone in" are different questions.
pub const VBC_ISSUING_MIN_REMAINING_SECS: u64 = protocol_gen::VBC_ISSUING_MIN_REMAINING_SECS;
/// Below this much remaining life, renewal is permitted.
pub const VBC_RENEWAL_WINDOW_SECS: u64 = protocol_gen::VBC_RENEWAL_WINDOW_SECS;
/// Lifetime of a provisional VBC — shorter than the unusable threshold, so it
/// is born unable to serve and no boundary case has to be argued.
pub const PROVISIONAL_VBC_EXPIRY_SECS: u64 = protocol_gen::PROVISIONAL_VBC_EXPIRY_SECS;

/// True when a VBC has too little life left to serve — the REMAINING-life
/// question, for the pre-expiry case (a full cert that must be renewed before
/// it lapses).
///
/// Takes the ATTESTED tick, not a local clock.
///
/// ⚠ RULE 0 §4 — CORRECTING A WRONG READING (2026-09-01). This doc comment
/// used to say the function was "used for BOTH the provisional case (born
/// below the threshold) and the pre-expiry case", and `AXIOM_DESIGN_
/// ValidatorJoin.md` §7 row 4b cited that as the reason a provisional could
/// not serve. **It was used for NEITHER: this function had ZERO production
/// callers** — only tests and one comment in `modes.rs`. The arithmetic was
/// true and enforced nothing, so a provisional presented as a witness
/// credential would have been accepted.
///
/// The provisional case is now handled by `vbc_is_provisional` (a LIFETIME
/// test, deliberately not this one — see its doc for why a remaining-life
/// test at a reliance site would retroactively strand honest wallets), called
/// from `validate_witnesses` and CL5.
///
/// This function is still UNCALLED in production: the pre-expiry unusable
/// band is not enforced anywhere, and a full VBC serves until `expires_at`.
/// Enforcing it needs a ruling on which clock a verifier may judge a peer's
/// cert against. Parked deliberately, not forgotten — ALLOW_CONST_PREDICATE.
#[inline]
pub fn vbc_can_serve(expires_at: u64, now: u64) -> bool {
    expires_at.saturating_sub(now) >= VBC_UNUSABLE_REMAINING_SECS
}

/// §5.3 — may the holder of this certificate ADMIT a new validator?
///
/// ⚠ This is the correct home for a remaining-life test, and it is worth
/// stating why, because the neighbouring `vbc_can_serve` was deliberately left
/// UNCALLED for the opposite reason.
///
/// A remaining-life test at a RELIANCE site is retroactive: it would refuse a
/// signature that was perfectly good when made, purely because the signer has
/// since aged, stranding wallets whose witness certificate merely got older.
/// That is why §5.2.2a tests provisional-ness on LIFETIME, never on remaining
/// life.
///
/// ISSUANCE is the opposite case. "May you admit someone RIGHT NOW" is a
/// present-tense question about the issuer, asked at the moment it acts.
/// Nothing retroactive about it.
#[inline]
pub fn vbc_can_issue(expires_at: u64, now: u64) -> bool {
    expires_at.saturating_sub(now) >= VBC_ISSUING_MIN_REMAINING_SECS
}

/// True when a VBC is inside its renewal window and not yet expired.
/// An EXPIRED cert is not renewable — that is what makes heritage loss real
/// (`AXIOM_DESIGN_ValidatorJoin.md` §5.2.2).
#[inline]
pub fn vbc_can_renew(expires_at: u64, now: u64) -> bool {
    expires_at > now && expires_at.saturating_sub(now) < VBC_RENEWAL_WINDOW_SECS
}

/// True when a certificate is PROVISIONAL — a candidate binding issued before
/// funding (`AXIOM_DESIGN_ValidatorJoin.md` §5.2.2), conferring no service
/// rights. Core bounds a provisional's lifetime at issuance
/// (`modes.rs::execute_cl8`), which is what makes this test meaningful: a
/// caller cannot mint a long-lived unstaked cert and a short lifetime is
/// therefore evidence that no stake was ever proved.
///
/// ⚠ This tests the cert's LIFETIME, never its REMAINING life, and the
/// distinction is load-bearing at every call site. A lifetime is fixed at
/// issuance, so the answer is identical at signing time and years later. A
/// remaining-life test at a reliance site (a witness set, a cheque) would be
/// RETROACTIVE: it would invalidate a receipt that was legitimately witnessed
/// while the signer's cert was healthy, stranding a wallet that did nothing
/// wrong. `vbc_can_serve` is the remaining-life question and answers a
/// different one — do not substitute it here.
///
/// ⚠ `expires_at == 0` is the "never expires" SENTINEL, not a zero-length
/// life. The whole VBC path reads it that way (`vbc.rs` skips both expiry
/// checks on it) and `validator_setup.rs` issues it for every non-genesis
/// cert. Without this arm, every sentinel cert on the mesh would classify as
/// provisional and stop being accepted as a witness — a fleet-wide outage
/// from a one-line omission.
#[inline]
pub fn vbc_is_provisional(issued_at: u64, expires_at: u64) -> bool {
    if expires_at == 0 {
        return false; // sentinel: never expires — see the note above
    }
    expires_at.saturating_sub(issued_at) <= PROVISIONAL_VBC_EXPIRY_SECS
}

