    fn ki54_canonical_burn_address_is_authorized() {
        let mut tx = create_test_transaction();
        tx.receiver_wallet_id = crate::types::BURN_ADDRESS.to_string();
        tx.burn_target_tx_id = Some([9u8; 32]);
        assert!(crate::fact::burn_target_is_authorized(&tx));
        assert_eq!(crate::fact::fact_burn_target(&tx), Some(&[9u8; 32]));
    }

