    #[test]
    fn test_dust_check_before_signature_check() {
        // Dust should be caught BEFORE expensive signature verification
        // Test with amount=1 and invalid signature — should get DustAmount, not InvalidSig
        let mut tx = create_test_transaction();
        tx.wallet_seq = 1;
        tx.amount = 500; // Below dust
        tx.client_sig = vec![0xFF; 64]; // Garbage signature
        
        let mut inputs = create_test_inputs(tx);
        inputs.current_state = Some(WalletState {
            wall_clock_lock: 0,
            emission_claimed_epoch: 0,
            stake_floor_until: 0, wallet_format: crate::types::WalletFormat::CURRENT,
            public_key: vec![0u8; 32],
            balance: 1_000_000,
            wallet_seq: 0,
            state_id: [0u8; 32],
            auth_hash: None,
            wallet_id: None,
            group_members: None, hibernation_until: 0,
        });
        
        let result = validate_transaction(&inputs).unwrap();
        // Must get DustAmount, not signature error — dust check comes first
        assert_eq!(result.result, ValidationResult::Reject);
        assert_eq!(result.rejection_reason, Some(ValidationError::DustAmount));
    }
    
