    #[test]
    fn test_overlap_true_genesis() {
        use crate::types::{VBCProofBundle, VBC};
        
        // Genesis TX (no prev_receipts) → check_validator_overlap returns Some(true)
        // We test the overlap function directly because validate_transaction
        // may reject the TX before reaching overlap check (e.g. invalid sig).
        let mut tx = create_test_transaction();
        tx.wallet_seq = 1;
        
        let mut inputs = create_test_inputs(tx);
        inputs.current_state = Some(WalletState {
            wall_clock_lock: 0,
            emission_claimed_epoch: 0,
            stake_floor_until: 0, wallet_format: crate::types::WalletFormat::CURRENT,
            public_key: vec![0u8; 32],
            balance: 1_000_000,
            wallet_seq: 0,
            state_id: [0u8; 32],
            auth_hash: None,
            wallet_id: None,
            group_members: None, hibernation_until: 0,
        });
        inputs.prev_receipts = vec![]; // Genesis
        inputs.vbc_bundle = Some(VBCProofBundle {
            target_vbc: VBC {
                genesis_lineage: [0u8; 32],
                network_size_baseline: 0,
                baseline_tick: 0,
                version: 0x09,
                validator_id: *blake3::hash(&[0xAA; 32]).as_bytes(),
                subject_pubkey_sphincs: vec![0xAA; 32],
                subject_pubkey_dilithium: vec![0u8; 1952],
                subject_pubkey_ed25519: vec![0xBB; 32],
                pgp_fingerprint: vec![],
                node_name: String::new(),
                proof_cap: String::new(),
                issued_at: 0,
                expires_at: u64::MAX,
                chain_depth: 0,
                issuer_set: vec![],
                signatures: vec![],
                max_tx: 0,
                founding_vbc_hash: [0u8; 32],
                nabla_registration: None,
            },
            supporting_vbcs: vec![],
            candidacy_pulse: None, renewal_work_receipt: None,
        });
        
        // Test overlap logic directly
        let overlap = check_validator_overlap(&inputs);
        assert_eq!(overlap, Some(true));
    }
    
    /// SEC-10 (call-site-guarding): `validate_vbc` must enforce the target VBC's
    /// expiry against the signed `tx.epoch` — i.e. the production `_no_time →
    /// tx.epoch` switch that IS the fix. A structurally-valid but EXPIRED VBC is
    /// rejected with `VBCExpired` at Step 7 of the chain walk, which runs BEFORE
    /// signature verification (Step 8) — so we don't need real SPHINCS sigs.
    ///
    /// FAILS-WITHOUT-FIX: with `verify_vbc_bundle_no_time` (current_time=0) the
    /// Step-7 expiry block is skipped, so the bundle proceeds to the sig check
    /// and fails with a DIFFERENT error (not `VBCExpired`). The earlier SEC-10
    /// test called `verify_vbc_bundle` directly and did not guard this switch.
    #[test]
    fn test_validate_vbc_enforces_expiry_against_tx_epoch() {
        let mut tx = create_test_transaction();
        tx.epoch = 5000; // trusted current time, well past the VBC's expiry
        let mut inputs = create_test_inputs(tx);
        inputs.vbc_bundle = Some(VBCProofBundle {
            target_vbc: VBC {
                genesis_lineage: [0u8; 32],
                network_size_baseline: 0,
                baseline_tick: 0,
                version: 0x09,
                validator_id: *blake3::hash(&[0xAA; 32]).as_bytes(),
                subject_pubkey_sphincs: vec![0xAA; 32],
                subject_pubkey_dilithium: vec![0u8; 1952],
                subject_pubkey_ed25519: vec![0xBB; 32],
                pgp_fingerprint: vec![],
                node_name: String::new(),
                proof_cap: String::new(),
                issued_at: 1000,
                expires_at: 2000, // EXPIRED relative to tx.epoch = 5000
                chain_depth: 0,
                // 3 distinct issuers + 3 sigs so Steps 3/4 pass and the walk
                // reaches Step 7 (expiry); sig bytes are never verified here.
                issuer_set: vec![vec![1u8; 32], vec![2u8; 32], vec![3u8; 32]],
                signatures: vec![vec![0u8; 7856], vec![0u8; 7856], vec![0u8; 7856]],
                max_tx: 0,
                founding_vbc_hash: [0u8; 32],
                nabla_registration: None,
            },
            supporting_vbcs: vec![],
            candidacy_pulse: None, renewal_work_receipt: None,
        });
        let result = validate_vbc(&inputs);
        assert!(
            matches!(result, Err(ValidationError::VBCExpired { .. })),
            "validate_vbc must reject an expired VBC at tx.epoch (got {:?}); FAILS if reverted to _no_time",
            result,
        );
    }

