    // ========================================================================
    // Group Wallet Tests
    // ========================================================================
    
    use crate::types::{GroupMember, MAX_GROUP_MEMBERS, TOTAL_SHARE_BPS};
    
    fn make_member(pk_byte: u8, share_bps: u16) -> GroupMember {
        GroupMember {
            member_pk: vec![pk_byte; 32],
            share_bps,
            available: 0,
        }
    }
    
    // --- Creation validation tests ---
    
    #[test]
    fn test_group_creation_valid_2_members() {
        let members = vec![
            make_member(1, 5000),
            make_member(2, 5000),
        ];
        assert!(validate_group_wallet_creation(&members).is_ok());
    }
    
    #[test]
    fn test_group_creation_valid_3_members() {
        let members = vec![
            make_member(1, 5000),
            make_member(2, 3000),
            make_member(3, 2000),
        ];
        assert!(validate_group_wallet_creation(&members).is_ok());
    }
    
    #[test]
    fn test_group_creation_valid_32_members() {
        let mut members = Vec::new();
        // 31 members at 312 bps each = 9672
        for i in 0..31u8 {
            members.push(make_member(i, 312));
        }
        // Last member gets remainder: 10000 - 9672 = 328
        members.push(make_member(31, 328));
        
        let total: u32 = members.iter().map(|m| m.share_bps as u32).sum();
        assert_eq!(total, 10000);
        assert_eq!(members.len(), 32);
        assert!(validate_group_wallet_creation(&members).is_ok());
    }
    
    #[test]
    fn test_group_creation_too_many_members() {
        let mut members = Vec::new();
        for i in 0..33u8 {
            members.push(make_member(i, 303));
        }
        // 33 > MAX_GROUP_MEMBERS
        let result = validate_group_wallet_creation(&members);
        assert!(result.is_err());
        assert_eq!(result.unwrap_err(), ValidationError::GroupTooManyMembers);
    }
    
