    // --- Distribution tests ---
    
    #[test]
    fn test_group_distribute_even_split() {
        let members = vec![
            make_member(1, 5000),  // 50%
            make_member(2, 5000),  // 50%
        ];
        let tx_hash = [0u8; 32];
        let updated = distribute_to_group(&members, 10000, &tx_hash).unwrap();
        assert_eq!(updated[0].available, 5000);
        assert_eq!(updated[1].available, 5000);
    }
    
    #[test]
    fn test_group_distribute_uneven_split() {
        let members = vec![
            make_member(1, 5000),  // 50%
            make_member(2, 3000),  // 30%
            make_member(3, 2000),  // 20%
        ];
        let tx_hash = [0u8; 32];
        let updated = distribute_to_group(&members, 10000, &tx_hash).unwrap();
        assert_eq!(updated[0].available, 5000);
        assert_eq!(updated[1].available, 3000);
        assert_eq!(updated[2].available, 2000);
        
        // Checksum
        let total: u64 = updated.iter().map(|m| m.available).sum();
        assert_eq!(total, 10000);
    }
    
    #[test]
    fn test_group_distribute_remainder() {
        let members = vec![
            make_member(1, 5000),  // 50%
            make_member(2, 3000),  // 30%
            make_member(3, 2000),  // 20%
        ];
        let tx_hash = [0u8; 32]; // tx_hash[0] = 0, 0 % 3 = 0 → member 0 gets remainder
        let updated = distribute_to_group(&members, 10001, &tx_hash).unwrap();
        
        // 10001 * 5000 / 10000 = 5000, * 3000/10000 = 3000, * 2000/10000 = 2000
        // distributed = 10000, remainder = 1
        // tx_hash[0] = 0, 0 % 3 = 0 → member 0 gets +1
        assert_eq!(updated[0].available, 5001); // got the remainder
        assert_eq!(updated[1].available, 3000);
        assert_eq!(updated[2].available, 2000);
        
        let total: u64 = updated.iter().map(|m| m.available).sum();
        assert_eq!(total, 10001);
    }
    
    #[test]
    fn test_group_distribute_remainder_different_hash() {
        let members = vec![
            make_member(1, 5000),
            make_member(2, 3000),
            make_member(3, 2000),
        ];
        let mut tx_hash = [0u8; 32];
        tx_hash[0] = 2; // 2 % 3 = 2 → member 2 gets remainder
        let updated = distribute_to_group(&members, 10001, &tx_hash).unwrap();
        
        assert_eq!(updated[0].available, 5000);
        assert_eq!(updated[1].available, 3000);
        assert_eq!(updated[2].available, 2001); // got the remainder
        
        let total: u64 = updated.iter().map(|m| m.available).sum();
        assert_eq!(total, 10001);
    }
    
    #[test]
    fn test_group_distribute_accumulates() {
        let members = vec![
            GroupMember { member_pk: vec![1; 32], share_bps: 5000, available: 1000 },
            GroupMember { member_pk: vec![2; 32], share_bps: 5000, available: 1000 },
        ];
        let tx_hash = [0u8; 32];
        let updated = distribute_to_group(&members, 10000, &tx_hash).unwrap();
        
        // Previous 1000 + new 5000 = 6000 each
        assert_eq!(updated[0].available, 6000);
        assert_eq!(updated[1].available, 6000);
    }
    
    #[test]
    fn test_group_distribute_large_amount() {
        let members = vec![
            make_member(1, 5000),
            make_member(2, 5000),
        ];
        let tx_hash = [0u8; 32];
        let amount = 1_000_000_000_000u64; // 1 trillion atoms
        let updated = distribute_to_group(&members, amount, &tx_hash).unwrap();
        assert_eq!(updated[0].available, 500_000_000_000);
        assert_eq!(updated[1].available, 500_000_000_000);
    }
    
    #[test]
    fn test_group_distribute_single_atom() {
        let members = vec![
            make_member(1, 5000),
            make_member(2, 3000),
            make_member(3, 2000),
        ];
        let tx_hash = [0u8; 32]; // member 0 gets remainder
        let updated = distribute_to_group(&members, 1, &tx_hash).unwrap();
        
        // 1 * 5000/10000 = 0, 1 * 3000/10000 = 0, 1 * 2000/10000 = 0
        // distributed = 0, remainder = 1 → member 0
        assert_eq!(updated[0].available, 1);
        assert_eq!(updated[1].available, 0);
        assert_eq!(updated[2].available, 0);
    }
    
