    // --- Full lifecycle test ---
    
    #[test]
    fn test_group_wallet_full_lifecycle() {
        // 1. Create group wallet with 3 members
        let members = vec![
            make_member(1, 5000),  // 50%
            make_member(2, 3000),  // 30%
            make_member(3, 2000),  // 20%
        ];
        assert!(validate_group_wallet_creation(&members).is_ok());
        
        // 2. Receive 100,000 atoms
        let tx_hash = [42u8; 32]; // 42 % 3 = 0 → member 0 gets remainder
        let updated = distribute_to_group(&members, 100_000, &tx_hash).unwrap();
        assert_eq!(updated[0].available, 50_000);
        assert_eq!(updated[1].available, 30_000);
        assert_eq!(updated[2].available, 20_000);
        
        // Checksum
        assert!(validate_group_checksum(&updated, 100_000).is_ok());
        
        // 3. Member 0 withdraws 30,000
        assert!(validate_group_withdrawal(&updated, 0, 30_000).is_ok());
        
        // 4. After withdrawal: member 0 has 20,000 left, balance = 70,000
        let mut after_withdraw = updated.clone();
        after_withdraw[0].available -= 30_000;
        assert!(validate_group_checksum(&after_withdraw, 70_000).is_ok());
        
        // 5. Receive another 10,000
        let tx_hash2 = [1u8; 32]; // 1 % 3 = 1 → member 1 gets remainder
        let updated2 = distribute_to_group(&after_withdraw, 10_000, &tx_hash2).unwrap();
        assert_eq!(updated2[0].available, 20_000 + 5_000);  // 25,000
        assert_eq!(updated2[1].available, 30_000 + 3_000);  // 33,000
        assert_eq!(updated2[2].available, 20_000 + 2_000);  // 22,000
        
        // Checksum: 25000 + 33000 + 22000 = 80000 = 70000 + 10000
        assert!(validate_group_checksum(&updated2, 80_000).is_ok());
        
        // 6. Member 2 tries to withdraw more than available
        assert!(validate_group_withdrawal(&updated2, 2, 30_000).is_err());
        
        // 7. Member 2 withdraws exactly their available
        assert!(validate_group_withdrawal(&updated2, 2, 22_000).is_ok());
    }

