    fn create_burn_inputs(
        scarred_tx_id: [u8; 32],
        scarred_amount: u64,
        burn_amount: u64,
    ) -> PublicInputs {
        use crate::types::{FactChain, FactLink, FactWitness, BURN_ADDRESS};
        let mut tx = create_test_transaction();
        tx.wallet_seq = 1;
        tx.receiver_wallet_id = BURN_ADDRESS.to_string();
        tx.amount = burn_amount;
        tx.burn_target_tx_id = Some(scarred_tx_id);

        let scarred_link = FactLink {
            tx_id: scarred_tx_id,
            previous_state_id: [0u8; 32],
            new_state_id: [1u8; 32],
            amount: scarred_amount,
            required_k: 3,
            tick: 0,
            witnesses: vec![
                FactWitness { validator_id: [1u8; 32], validator_pk: vec![0u8; 1952], signature: vec![0u8; 3309], vbc_hash: [0u8; 32] },
                FactWitness { validator_id: [2u8; 32], validator_pk: vec![0u8; 1952], signature: vec![0u8; 3309], vbc_hash: [0u8; 32] },
                FactWitness { validator_id: [3u8; 32], validator_pk: vec![0u8; 1952], signature: vec![0u8; 3309], vbc_hash: [0u8; 32] },
            ],
            nabla_confirmation: None, // SCARRED
            burn_proof: None,
            burn_target_tx_id: None,
            sender_anchor: None,
            is_dev_class: false,
            recall_proof: None,
            out_of_order_confirmation: None,
            inherited_scar_txids: Vec::new(),
            inherited_scar_resolutions: Vec::new(),
            receiver_witness: None,
        };

        let mut inputs = create_test_inputs(tx);
        inputs.current_state = Some(WalletState {
            wall_clock_lock: 0,
            emission_claimed_epoch: 0,
            stake_floor_until: 0, wallet_format: crate::types::WalletFormat::CURRENT,
            public_key: vec![0u8; 32],
            balance: 1_000_000,
            wallet_seq: 0,
            state_id: [0u8; 32],
            auth_hash: None,
            wallet_id: None,
            group_members: None, hibernation_until: 0,
        });
        inputs.sender_fact_chain = Some(FactChain {
            checkpoint: None,
            links: vec![scarred_link],
        });
        inputs
    }

    /// KI#241 F-9.4 (Fable review 2026-10-01, F-9 test 6) — the FACT depth
    /// gate exempts the YPX-001 §1.5.4 `BURN_ADDRESS`+target burn: on a
    /// 17-link chain with `max_fact_links = 16` it is NOT `FactChainTooDeep`
    /// (it proceeds to the later gates). A plain send and a TARGETLESS
    /// `BURN_ADDRESS` send (a donation, not a burn) on the same chain still are.
    /// MUTATION (run 2026-10-01): revert `depth_exempt` to `is_heal_self_send`
    /// ⇒ the burn is `FactChainTooDeep` ⇒ RED.
    #[test]
    fn ki241_burn_address_burn_is_depth_exempt_plain_send_is_not() {
        use crate::types::BURN_ADDRESS;
        let deep = |mut inputs: PublicInputs| {
            let fc = inputs.sender_fact_chain.as_mut().unwrap();
            let tmpl = fc.links[0].clone();
            for i in 0..16u8 {
                let mut l = tmpl.clone();
                l.tx_id = [0xD0 ^ i; 32];
                fc.links.insert(0, l);
            }
            assert_eq!(fc.links.len(), 17, "fixture: one link over the operator cap");
            inputs.max_fact_links = Some(16);
            inputs
        };
        let burn = deep(create_burn_inputs([42u8; 32], 100_000, 100_000));
        let r = validate_transaction(&burn).unwrap();
        assert_ne!(r.rejection_reason, Some(ValidationError::FactChainTooDeep),
            "a BURN_ADDRESS+target burn must be depth-exempt (got {:?})", r.rejection_reason);

        let mut plain = deep(create_burn_inputs([42u8; 32], 100_000, 100_000));
        plain.transaction.receiver_wallet_id = create_test_transaction().receiver_wallet_id;
        plain.transaction.burn_target_tx_id = None;
        plain.transaction.amount = create_test_transaction().amount;
        assert_eq!(validate_transaction(&plain).unwrap().rejection_reason, Some(ValidationError::FactChainTooDeep),
            "a plain send on the same chain is still gated");

        let mut donation = deep(create_burn_inputs([42u8; 32], 100_000, 100_000));
        assert_eq!(donation.transaction.receiver_wallet_id, BURN_ADDRESS);
        donation.transaction.burn_target_tx_id = None;
        donation.transaction.amount = create_test_transaction().amount;
        assert_eq!(validate_transaction(&donation).unwrap().rejection_reason, Some(ValidationError::FactChainTooDeep),
            "a targetless BURN_ADDRESS send is not a burn — still gated");
    }

