    // ====================================================================
    // Per-wallet scar cap (S7c)
    // ====================================================================

    fn make_scarred_link(tx_id: u8) -> crate::types::FactLink {
        crate::types::FactLink {
            tx_id: {
                let mut id = [0u8; 32];
                id[0] = tx_id;
                id
            },
            previous_state_id: [0u8; 32],
            new_state_id: [0u8; 32],
            amount: 1000,
            required_k: 3,
            tick: 1,
            witnesses: vec![],
            nabla_confirmation: None,  // scarred — no confirmation
            burn_proof: None,          // not burned either
            burn_target_tx_id: None,
            sender_anchor: None,
            is_dev_class: false,
            recall_proof: None,
            out_of_order_confirmation: None,
            inherited_scar_txids: Vec::new(),
            inherited_scar_resolutions: Vec::new(),
            receiver_witness: None,
        }
    }

    fn make_healed_link(tx_id: u8) -> crate::types::FactLink {
        let mut link = make_scarred_link(tx_id);
        link.nabla_confirmation = Some(crate::types::NablaConfirmation {
            nabla_node_id: [1u8; 32],
            nabla_signature: vec![0u8; 64],
            root_hash: [2u8; 32],
            synced_to_tick: 100,
            ..Default::default()
        });
        link
    }


    // ── KI#58: the cap must not lock a wallet out of its own recovery ──
    //
    // Pre-fix the exemption was `receiver == BURN_ADDRESS && burn_target.is_some()`,
    // a shape the SDK never builds (its burn is a SELF-SEND), and heal was not
    // exempt at all. A wallet at 21+ unresolved scars could not send, heal, OR
    // burn — while the comment above the gate promised it "must always be able
    // to burn scars to recover".

    #[test]
    fn ki58_self_send_heal_burn_is_exempt_over_cap() {
        // THE shape the SDK actually builds: is_heal + sender == receiver,
        // carrying a burn target. Must clear the cap.
        let mut tx = create_test_transaction();
        tx.kind = crate::types::TxKind::Heal;
        tx.receiver_wallet_id = tx.sender_wallet_id.clone();
        tx.burn_target_tx_id = Some([7u8; 32]);
        let mut inputs = create_test_inputs(tx);
        let links: Vec<_> = (0..=(MAX_UNRESOLVED_SCARS as u8)).map(make_scarred_link).collect();
        inputs.sender_fact_chain = Some(crate::types::FactChain { links, checkpoint: None });
        let result = validate_transaction(&inputs).unwrap();
        assert_ne!(result.rejection_reason, Some(ValidationError::TooManyUnresolvedScars),
            "the SDK's real burn shape must be able to recover a wallet over the cap");
    }

    #[test]
    fn ki58_plain_heal_is_exempt_over_cap() {
        // Design decision 2026-08-03: heal exempt too. Heal is how a backlog is worked
        // down; capping it turns a recoverable backlog into a wedge.
        let mut tx = create_test_transaction();
        tx.kind = crate::types::TxKind::Heal;
        let mut inputs = create_test_inputs(tx);
        let links: Vec<_> = (0..=(MAX_UNRESOLVED_SCARS as u8)).map(make_scarred_link).collect();
        inputs.sender_fact_chain = Some(crate::types::FactChain { links, checkpoint: None });
        let result = validate_transaction(&inputs).unwrap();
        assert_ne!(result.rejection_reason, Some(ValidationError::TooManyUnresolvedScars),
            "heal must clear the cap or a wallet cannot work its backlog down");
    }

    fn make_recall_link(tx_id: u8) -> crate::types::FactLink {
        let mut l = make_scarred_link(tx_id);
        let mut txid = [0u8; 32];
        txid[0] = tx_id;
        l.recall_proof = Some(crate::types::RecallAttestation {
            txid,
            presend_state_hash: [0u8; 32],
            amount: 1000,
            recall_tick: 1,
            nabla_node_pk: [0u8; 32],
            nabla_signature: vec![],
            nbc_issuer_pk: vec![],
            nbc_signature: vec![],
            nbc_commitment: vec![],
        });
        l
    }

    #[test]
    fn recall_resolved_link_not_counted_toward_cap() {
        // YPX-022 / Audit#3: a recall_proof resolves the link → it MUST NOT count
        // toward the 20-scar cap. Before the fix the inline nabla+burn-only filter
        // counted recalled links, so a recalled wallet wedged at the cap.
        // Contrast with `test_scar_cap_exceeded_rejects` (21 SCARRED → rejects).
        let mut inputs = create_test_inputs(create_test_transaction());
        let links: Vec<_> = (0..=(MAX_UNRESOLVED_SCARS as u8)).map(make_recall_link).collect();
        inputs.sender_fact_chain = Some(crate::types::FactChain { links, checkpoint: None });
        let result = validate_transaction(&inputs).unwrap();
        assert_ne!(result.rejection_reason, Some(ValidationError::TooManyUnresolvedScars),
            "recall-resolved links must not count toward the scar cap");
    }

    #[test]
    fn ki58_zkvm_checkpoint_heal_is_exempt_over_cap() {
        // KI#58 (Audit#2): the zkVM checkpoint (modes.rs) must exempt heal from the
        // cap EXACTLY like DMAP (validation.rs). Before the fix it used `if !is_burn`
        // — so it REJECTED a heal at >20 scars that DMAP ACCEPTED (two-VM divergence,
        // the KI#54 shape, invisible to the differential for lack of a vector).
        let mut tx = create_test_transaction();
        tx.kind = crate::types::TxKind::Heal;
        let mut inputs = create_test_inputs(tx);
        let links: Vec<_> = (0..=(MAX_UNRESOLVED_SCARS as u8)).map(make_scarred_link).collect();
        inputs.sender_fact_chain = Some(crate::types::FactChain { links, checkpoint: None });
        let result = crate::modes::execute_cl3_zkp_checkpoint(&inputs, None);
        assert_ne!(result.rejection_reason, Some(ValidationError::TooManyUnresolvedScars),
            "zkVM checkpoint must exempt heal from the cap, matching DMAP (KI#58)");
    }

    #[test]
    fn ki58_zkvm_checkpoint_ordinary_send_over_cap_still_rejects() {
        // THE zkVM CONTROL: the cap must still bite for a normal send in the
        // checkpoint too, or the exemption above would pass against `cap_exempt=true`.
        let mut tx = create_test_transaction();
        tx.receiver_wallet_id = "someone-else@axiom/deadbeef".to_string();
        let mut inputs = create_test_inputs(tx);
        let links: Vec<_> = (0..=(MAX_UNRESOLVED_SCARS as u8)).map(make_scarred_link).collect();
        inputs.sender_fact_chain = Some(crate::types::FactChain { links, checkpoint: None });
        let result = crate::modes::execute_cl3_zkp_checkpoint(&inputs, None);
        assert_eq!(result.rejection_reason, Some(ValidationError::TooManyUnresolvedScars),
            "zkVM ordinary send over cap MUST still reject (cap not deleted)");
    }

