    #[test]
    fn test_version_with_phase_suffix_accepted() {
        // The phase-marker generalization (24958220, 2026-06-09) makes
        // any `Kyoto/1.1/<phase>` string compatible. Phases are
        // informational by design — see version.rs preamble. Real interop
        // is enforced by CoreID match (BLAKE3 of axiom-core.elf), not by
        // the version string. The actual security gate (different build
        // number) is covered by test_old_build_number_rejected below.
        let mut tx = create_test_transaction();
        tx.core_version = "Kyoto/2.12.0/DMAP".into();
        let inputs = create_test_inputs(tx);
        let result = validate_transaction(&inputs).unwrap();
        assert_ne!(result.rejection_reason, Some(ValidationError::VersionMismatch));

        let mut tx2 = create_test_transaction();
        tx2.core_version = "Kyoto/2.12.0/GENESIS".into();
        let inputs2 = create_test_inputs(tx2);
        let result2 = validate_transaction(&inputs2).unwrap();
        assert_ne!(result2.rejection_reason, Some(ValidationError::VersionMismatch));
    }

    #[test]
    fn test_old_build_number_rejected() {
        // Pre-cleanup builds used "Kyoto/1.01" — incompatible now.
        let mut tx = create_test_transaction();
        tx.core_version = "Kyoto/1.01".into();
        let inputs = create_test_inputs(tx);
        let result = validate_transaction(&inputs).unwrap();
        assert_eq!(result.rejection_reason, Some(ValidationError::VersionMismatch));
    }

    // =========================================================================
    // YPX-007: Receiver Security — E2E through Core CL2
    // =========================================================================
    // Tests use extract_security_level directly to verify extraction logic,
    // and validate_transaction for rejection path tests (Ark, tampered).
    // Full accept-path extraction is tested by validate_transaction only when
    // the TX has a real signature — here we test the extraction + routing layer.

    #[test]
    fn test_ypx007_standard_address_extracts_k3_dmap() {
        use crate::wallet_id::extract_security_level;
        let wid = generate_wallet_id_full("bob@test.com", "42", &WALLET_IDENTITY_KEY, &test_pk(), 3, 1).unwrap();
        let (k, pt) = extract_security_level(&wid).unwrap();
        assert_eq!(k, 3);
        assert_eq!(pt, 1); // DMAP
    }

