    #[test]
    fn test_ypx007_ark_address_rejected() {
        // Ark tier: k=0 — now accepted (§6.9: loading an Ark wallet).
        // The TX proceeds past Ark check and may fail on other validation
        // (e.g., signature), but NOT on ArkNotImplemented.
        let wid = generate_wallet_id_full("bob@test.com", "42", &WALLET_IDENTITY_KEY, &test_pk(), 0, 2).unwrap();
        let mut tx = create_test_transaction();
        tx.receiver_wallet_id = wid;
        let mut inputs = create_test_inputs(tx);
        inputs.current_state = Some(crate::types::WalletState {
            wall_clock_lock: 0,
            emission_claimed_epoch: 0,
            stake_floor_until: 0, wallet_format: crate::types::WalletFormat::CURRENT,
            public_key: vec![0u8; 32],
            balance: 1_000_000,
            wallet_seq: 0,
            state_id: [0u8; 32],
            auth_hash: None,
            wallet_id: None,
            group_members: None, hibernation_until: 0,
        });
        let result = validate_transaction(&inputs).unwrap();
        // Ark addresses should NOT be rejected with ArkNotImplemented.
        // May accept (if fake sig passes) or reject for other reasons — either is fine.
        assert_ne!(result.rejection_reason, Some(ValidationError::ArkNotImplemented),
                   "Ark addresses should no longer be rejected with ArkNotImplemented");
    }

    #[test]
    fn test_ypx007_tampered_address_rejected() {
        // Generate a valid Standard address, then tamper with the checksum
        let wid = generate_wallet_id_full("bob@test.com", "42", &WALLET_IDENTITY_KEY, &test_pk(), 3, 1).unwrap();
        // Flip one hex char in checksum
        let mut chars: Vec<char> = wid.chars().collect();
        let slash_pos = wid.rfind('/').unwrap();
        let first_hex = chars[slash_pos + 1];
        chars[slash_pos + 1] = if first_hex == 'a' { 'b' } else { 'a' };
        let tampered: String = chars.into_iter().collect();

        let mut tx = create_test_transaction();
        tx.receiver_wallet_id = tampered;
        let inputs = create_test_inputs(tx);
        let result = validate_transaction(&inputs).unwrap();
        // No checksum matches any tier → rejected
        assert_eq!(result.result, ValidationResult::Reject);
    }

    #[test]
    fn test_ypx007_same_email_all_tiers_same_core_result() {
        // All 7 addresses for the same person: extraction works for all tiers
        // (except Ark which is rejected by Core CL2)
        use crate::wallet_id::{generate_all_wallet_ids, extract_security_level, K_ARK};

        let all = generate_all_wallet_ids("charlie@test.com", "55", &test_pk()).unwrap();
        assert_eq!(all.len(), 7);

        for (wid, k, pt, name) in &all {
            if *k == K_ARK {
                // Ark: verify extraction returns k=0, proof_type=2
                let (ek, ept) = extract_security_level(wid).unwrap();
                assert_eq!(ek, 0, "Ark should have k=0");
                assert_eq!(ept, 2, "Ark should have proof_type=2");
            } else {
                // Non-Ark: verify extraction returns correct (k, proof_type)
                let (ek, ept) = extract_security_level(wid).unwrap();
                assert_eq!(ek, *k,
                    "{}: expected required_k={}, got {}", name, k, ek);
                assert_eq!(ept, *pt,
                    "{}: expected proof_type={}, got {}", name, pt, ept);
            }
        }
    }

    #[test]
    fn test_frozen_wallet_rejected() {
        let mut tx = create_test_transaction();
        tx.client_pk = vec![0xAA; 32]; // Sender PK
        tx.wallet_seq = 1;

        let mut inputs = create_test_inputs(tx);
        inputs.current_state = Some(WalletState {
            wall_clock_lock: 0,
            emission_claimed_epoch: 0,
            stake_floor_until: 0, wallet_format: crate::types::WalletFormat::CURRENT,
            public_key: vec![0xAA; 32],
            balance: 1_000_000,
            wallet_seq: 0,
            state_id: [0u8; 32],
            auth_hash: None,
            wallet_id: None,
            group_members: None, hibernation_until: 0,
        });

        // Add sender's PK to frozen_wallets
        inputs.frozen_wallets = Some(vec![[0xAA; 32]]);

        let result = validate_transaction(&inputs).unwrap();
        assert_eq!(result.result, ValidationResult::Reject,
            "Transaction from frozen wallet should be rejected");
        assert_eq!(result.rejection_reason, Some(ValidationError::WalletFrozen),
            "Rejection reason should be WalletFrozen");
    }

    #[test]
    fn test_sec08_frozen_wallet_cannot_burn() {
        // SEC-08 un-burnable: a frozen wallet must not be able to SELF-DESTRUCT
        // (burn to BURN_ADDRESS) either — funds are preserved in place, not
        // destroyable by a coercer. The frozen-set gate (validation.rs ~538) runs
        // at the TOP of validate_transaction, ahead of burn detection and the
        // KI#13 burn carve-out, and checks tx.client_pk regardless of tx kind —
        // so a burn from a frozen sender is rejected with WalletFrozen, never
        // reaching the burn logic. This test fails if the gate is ever moved
        // below the burn handling.
        let mut tx = create_test_transaction();
        tx.client_pk = vec![0xAA; 32];
        tx.wallet_seq = 1;
        // Make it a burn TX.
        tx.receiver_wallet_id = crate::types::BURN_ADDRESS.to_string();
        tx.burn_target_tx_id = Some([0x77; 32]);

        let mut inputs = create_test_inputs(tx);
        inputs.current_state = Some(WalletState {
            wall_clock_lock: 0,
            emission_claimed_epoch: 0,
            stake_floor_until: 0, wallet_format: crate::types::WalletFormat::CURRENT,
            public_key: vec![0xAA; 32],
            balance: 1_000_000,
            wallet_seq: 0,
            state_id: [0u8; 32],
            auth_hash: None,
            wallet_id: None,
            group_members: None, hibernation_until: 0,
        });
        inputs.frozen_wallets = Some(vec![[0xAA; 32]]);

        let result = validate_transaction(&inputs).unwrap();
        assert_eq!(result.result, ValidationResult::Reject,
            "Burn from a frozen wallet must be rejected");
        assert_eq!(result.rejection_reason, Some(ValidationError::WalletFrozen),
            "A frozen wallet must be un-burnable — frozen gate ahead of the burn carve-out");
    }

    #[test]
    fn test_unfrozen_wallet_not_frozen_rejected() {
        // Verify a wallet NOT in the frozen list does not get WalletFrozen rejection.
        // (It may still be rejected for other reasons — we only check the reason.)
        let mut tx = create_test_transaction();
        tx.client_pk = vec![0xBB; 32]; // Sender PK (not frozen)
        tx.wallet_seq = 1;

        let mut inputs = create_test_inputs(tx);
        inputs.current_state = Some(WalletState {
            wall_clock_lock: 0,
            emission_claimed_epoch: 0,
            stake_floor_until: 0, wallet_format: crate::types::WalletFormat::CURRENT,
            public_key: vec![0xBB; 32],
            balance: 1_000_000,
            wallet_seq: 0,
            state_id: [0u8; 32],
            auth_hash: None,
            wallet_id: None,
            group_members: None, hibernation_until: 0,
        });

        // Freeze a different wallet — sender should not be affected
        inputs.frozen_wallets = Some(vec![[0xCC; 32]]);

        let result = validate_transaction(&inputs).unwrap();
        // The TX may still be rejected for other reasons (signature, etc.)
        // but NOT because of WalletFrozen
        assert_ne!(result.rejection_reason, Some(ValidationError::WalletFrozen),
            "Unfrozen wallet should not get WalletFrozen rejection");
    }

