    /// YPX-020 HAL: a `HalReanchor` self-send must be EXEMPT from the no-self-send
    /// rule — it re-anchors X→X' by construction. Without the exemption the
    /// re-anchor can never be built and a dead-overlap wallet is bricked. Fails if
    /// `is_hal_reanchor()` is dropped from the Rule-4 guard. (YPX-020 §2: completion
    /// is no longer a self-send — it is the distress-cheque redeem.)
    #[test]
    fn test_hal_self_send_exempt_from_self_send_rule() {
        let email = "alice@test.com";
        let sender_wid = generate_wallet_id(email, "42", &test_pk()).unwrap();
        // Same email, different security level → a self-send that Rule 4 would
        // normally reject.
        let all = generate_all_wallet_ids(email, "42", &test_pk()).unwrap();
        let receiver_wid = all.iter()
            .find(|(_, k, _, _)| *k == 4)
            .map(|(addr, _, _, _)| addr.clone())
            .unwrap();

        for kind in [crate::types::TxKind::HalReanchor] {
            let kname = format!("{:?}", kind);
            let mut tx = create_test_transaction();
            tx.sender_wallet_id = sender_wid.clone();
            tx.receiver_wallet_id = receiver_wid.clone();
            tx.wallet_seq = 1;
            tx.amount = 100_000;
            tx.kind = kind;

            let mut inputs = create_test_inputs(tx);
            inputs.current_state = Some(WalletState {
                wall_clock_lock: 0,
                emission_claimed_epoch: 0,
                stake_floor_until: 0, wallet_format: crate::types::WalletFormat::CURRENT,
                public_key: vec![0u8; 32],
                balance: 1_000_000,
                state_id: [0u8; 32],
                wallet_seq: 0,
                auth_hash: None,
                wallet_id: None,
                group_members: None, hibernation_until: 0,
            });

            let result = validate_transaction(&inputs).unwrap();
            assert_ne!(result.rejection_reason, Some(ValidationError::SelfSendRejected),
                "{} self-send must NOT trip SelfSendRejected (it re-anchors X→X')", kname);
        }
    }

    #[test]
    /// §5.2.2d — a certificate request is a SELF-TRANSACTION and must clear
    /// the self-send rule, exactly as heal / HAL / claim do.
    ///
    /// ⚠ WHY THIS MATTERS MORE THAN IT LOOKS. Without the exemption the round
    /// dies at `SelfSendRejected` before any issuer sees it, so a candidate can
    /// never obtain the PROVISIONAL certificate that the §5.2.2b subsidy gate
    /// now demands — and the subsidy path becomes unreachable rather than
    /// merely gated. That is a worse failure than the hole it replaced: the
    /// hole let the wrong wallets in, this would let nobody in.
    ///
    /// Found by driving the real flow on a live mesh, not by reading the code.
    #[test]
    fn a_vbc_request_is_exempt_from_the_self_send_rule() {
        let email = "candidate@test.com";
        let sender_wid = generate_wallet_id(email, "42", &test_pk()).unwrap();
        let all = generate_all_wallet_ids(email, "42", &test_pk()).unwrap();
        let receiver_wid = all.iter()
            .find(|(_, k, _, _)| *k == 4)
            .map(|(addr, _, _, _)| addr.clone())
            .unwrap();

        let mut tx = create_test_transaction();
        tx.sender_wallet_id = sender_wid;
        tx.receiver_wallet_id = receiver_wid;
        tx.wallet_seq = 1;
        tx.amount = 100_000;
        tx.kind = crate::types::TxKind::VbcRequest;

        let mut inputs = create_test_inputs(tx);
        inputs.current_state = Some(WalletState {
            wall_clock_lock: 0,
            emission_claimed_epoch: 0,
            stake_floor_until: 0, wallet_format: crate::types::WalletFormat::CURRENT,
            public_key: vec![0u8; 32],
            balance: 1_000_000,
            state_id: [0u8; 32],
            wallet_seq: 0,
            auth_hash: None,
            wallet_id: None,
            group_members: None,
            hibernation_until: 0,
        });

        let result = validate_transaction(&inputs).unwrap();
        assert_ne!(
            result.rejection_reason,
            Some(ValidationError::SelfSendRejected),
            "a VbcRequest self-send must NOT trip SelfSendRejected — the \
             candidate asks three issuers to sign ITS OWN certificate, so \
             there is no counterparty to address",
        );
    }

    /// §5.2.2b — "wallet generated, and immediately a provisional VBC is
    /// issued": the binding precedes the funding, so an EMPTY wallet must be
    /// able to request one. The request carries amount 0 and moves no value.
    /// FAILS-WITHOUT-FIX: `verify_balance` returned ZeroAmount, the CL1 dust
    /// gate returned ZeroAmount, and `compute_post_tx_balance` underflowed on
    /// the dust the SDK used to send (2026-09-08).
    #[test]
    fn test_vbc_request_from_an_empty_wallet_is_free_and_moves_no_value() {
        let email = "candidate@test.com";
        let sender_wid = generate_wallet_id(email, "42", &test_pk()).unwrap();
        let all = generate_all_wallet_ids(email, "42", &test_pk()).unwrap();
        let receiver_wid = all.iter()
            .find(|(_, k, _, _)| *k == 4)
            .map(|(addr, _, _, _)| addr.clone())
            .unwrap();

        let mut tx = create_test_transaction();
        tx.sender_wallet_id = sender_wid;
        tx.receiver_wallet_id = receiver_wid;
        tx.wallet_seq = 1;
        tx.amount = 0;
        tx.kind = crate::types::TxKind::VbcRequest;

        // The two balance rules, directly.
        assert_eq!(verify_balance(&tx, 0, false), Ok(()), "an empty wallet may request its binding");
        assert_eq!(compute_post_tx_balance(&tx, 0), Ok(0), "a VBC request moves no value");
        assert_eq!(compute_post_tx_balance(&tx, 7), Ok(7));

        // The CL1 gate as a whole: none of the amount rules may fire.
        let mut inputs = create_test_inputs(tx.clone());
        inputs.current_state = Some(WalletState {
            wall_clock_lock: 0,
            emission_claimed_epoch: 0,
            stake_floor_until: 0, wallet_format: crate::types::WalletFormat::CURRENT,
            public_key: vec![0u8; 32],
            balance: 0,
            state_id: [0u8; 32],
            wallet_seq: 0,
            auth_hash: None,
            wallet_id: None,
            group_members: None,
            hibernation_until: 0,
        });
        let result = validate_transaction(&inputs).unwrap();
        for bad in [ValidationError::ZeroAmount, ValidationError::DustAmount, ValidationError::InsufficientBalance] {
            assert_ne!(result.rejection_reason, Some(bad.clone()),
                "a zero-amount VbcRequest from an empty wallet must not be refused for its amount: {:?}", bad);
        }

        // Mutation guard: an ORDINARY zero-amount send is still refused.
        let mut plain = tx;
        plain.kind = crate::types::TxKind::Normal;
        assert_eq!(verify_balance(&plain, 0, false), Err(ValidationError::ZeroAmount));
    }

