    /// W7 / YPX-010 §11.7: Ark→Ark has two legitimate appearances — OFFLINE (the
    /// receiver-as-witness trade) and ONLINE (its §12 settlement, the same tx replayed
    /// through the witnessed pipeline). Because an Ark→Ark tx can only be offline, its
    /// appearance on the online path IS the settlement signal (derived from tier +
    /// context, no `is_settlement` flag). Neither is rejected by the retired
    /// `ArkOnlineTradeRejected` "online ban" — a forged online Ark trade is adjudicated
    /// by the normal path (consume-once + receiver-witness + k=3 round), not by a
    /// category ban here.
    #[test]
    fn test_ark_to_ark_never_online_banned() {
        let ark_of = |email: &str, pk: &[u8; 32]| {
            generate_all_wallet_ids(email, "42", pk).unwrap()
                .into_iter().find(|(_, k, _, _)| *k == 0).map(|(a, _, _, _)| a).unwrap()
        };
        let base_tx = || {
            let mut tx = create_test_transaction();
            tx.sender_wallet_id = ark_of("alice@test.com", &test_pk());
            tx.receiver_wallet_id = ark_of("bob@test.com", &[0x99u8; 32]); // different Ark wallet
            tx.wallet_seq = 1;
            tx.amount = 100_000;
            tx
        };
        let state = || Some(WalletState {
            wall_clock_lock: 0,
            emission_claimed_epoch: 0,
            stake_floor_until: 0, wallet_format: crate::types::WalletFormat::CURRENT,
            public_key: vec![0u8; 32], balance: 1_000_000, state_id: [0u8; 32],
            wallet_seq: 0, auth_hash: None, wallet_id: None,
            group_members: None, hibernation_until: 0,
        });

        // ONLINE (validator context) = the settlement signal → NOT online-banned;
        // it flows through to normal validation.
        let mut online = create_test_inputs(base_tx());
        online.current_state = state();
        online.my_validator_pk = Some(vec![0x77u8; 32]);
        assert_ne!(
            validate_transaction(&online).unwrap().rejection_reason,
            Some(ValidationError::ArkOnlineTradeRejected),
            "online Ark→Ark is the settlement signal, not a banned category (§12.1)");

        // OFFLINE (no validator apparatus) = the receiver-as-witness trade → likewise
        // not online-banned.
        let mut offline = create_test_inputs(base_tx());
        offline.current_state = state();
        assert_ne!(
            validate_transaction(&offline).unwrap().rejection_reason,
            Some(ValidationError::ArkOnlineTradeRejected),
            "offline Ark→Ark (receiver-as-witness) must NOT be online-banned");
    }

