    // ════════════════════════════════════════════════════════════════
    // Oracle VBC freshness (YPX-012 §2.5)
    // ════════════════════════════════════════════════════════════════

    /// Helper: build a WitnessSig with a VBC that has the given issued_at.
    fn make_witness_with_vbc_age(issued_at: u64) -> crate::types::WitnessSig {
        use crate::types::{WitnessSig, VBCProofBundle, VBC};
        use ed25519_dalek::Signer;
        let sk = ed25519_dalek::SigningKey::from_bytes(&[0x77; 32]);
        let pk = sk.verifying_key().to_bytes().to_vec();
        let sphincs_pk = vec![0xAA; 32];
        let vid = *blake3::hash(&sphincs_pk).as_bytes();
        WitnessSig {
            validator_id: vid,
            validator_pk: pk.clone(),
            vbc_bundle: Some(VBCProofBundle {
                target_vbc: VBC {
                    genesis_lineage: [0u8; 32],
                    network_size_baseline: 0,
                    baseline_tick: 0,
                    version: 0x09,
                    validator_id: vid,
                    subject_pubkey_sphincs: sphincs_pk,
                    subject_pubkey_dilithium: vec![0u8; 1952],
                    subject_pubkey_ed25519: vec![0u8; 32],
                    pgp_fingerprint: vec![],
                    node_name: String::new(),
                    proof_cap: String::new(),
                    issued_at,
                    expires_at: u64::MAX,
                    chain_depth: 0,
                    issuer_set: vec![],
                    signatures: vec![],
                    max_tx: 0,
                    founding_vbc_hash: [0u8; 32],
                    nabla_registration: None,
                },
                supporting_vbcs: vec![],
                candidacy_pulse: None, renewal_work_receipt: None,
            }),
            carrier_type: String::new(),
            carrier_address: String::new(),
            signature: sk.sign(&[0u8; 32]).to_bytes().to_vec(),
            execution_proof: vec![],
            proof_type: 1,
            availability_attestation: None,
            validator_hints: vec![],
            fact_signature: None,
            checkpoint_sig: None,
            receipt_signature: None,
                receipt_commitment_sig: None,
                rate_bps: 0,
                slot_amount: 0,
        }
    }

    #[test]
    fn test_oracle_vbc_too_old_rejected() {
        use crate::types::Receipt;
        let mut tx = create_test_transaction();
        tx.epoch = 200_000; // KI#131: window is now 86_400s (24h); epoch must exceed it
        tx.amount = 0;
        // Oracle requires sender == receiver (self-payout). Use valid wallet_id for both.
        tx.sender_wallet_id = tx.receiver_wallet_id.clone();
        let living_sig = crate::oracle::living_signature(&tx.sender_wallet_id);
        tx.oracle_claim = Some(crate::types::OracleClaimData {
            platform_url: "https://foldingathome.org".into(),
            user_id: 1,
            username: format!("user_{}", living_sig),
            credit_total: 100_000,
            credit_delta: 10_000,
            payout_amount: 0,
            zktls_proof: None,
        });
        let mut inputs = create_test_inputs(tx);
        // §15: anchor prev_receipt.state_hash to the default test current_state
        // (pk=test_signing_key, balance=100_000_000_000, seq=0) so the anchor
        // check passes — the test wants to assert OracleVBCTooOld, not StateNotAnchored.
        let anchored_sh = crate::crypto::compute_state_hash(
            &test_signing_key().verifying_key().to_bytes().to_vec(),
            100_000_000_000u64, 0u64, 0, 0, 0, 0, &crate::types::WalletFormat::CURRENT);
        // VBC issued_at = 200_000 - 86_401 → age = 86_401 > ORACLE_VBC_RENEWAL_SECS (KI#131)
        let stale_witness = make_witness_with_vbc_age(200_000 - 86_401);
        inputs.prev_receipts = vec![Receipt {
            oods_flag: None,
            confidence_index: None,
            sender_state: None,
            txid: [0u8; 32], state_hash: anchored_sh, produced_state_id: [0u8; 32],
            new_wallet_seq: 0, commitment_hash: [0u8; 32], sdid: [0u8; 32],
            lineage_hash: [0u8; 32], core_version: String::new(), core_id: [0u8; 32],
            witness_sigs: vec![stale_witness], epoch: 0, fact_proof: None,
            required_k: 3,
            receipt_commitment: [0u8; 32],
            fee_breakdown: Vec::new(),
            is_dev_class: false,
        }];
        let result = validate_transaction(&inputs).unwrap();
        assert_eq!(result.rejection_reason, Some(ValidationError::OracleVBCTooOld),
            "Oracle witness VBC older than 24h must be rejected");
    }

