    #[test]
    fn test_oracle_scarred_stake_rejected() {
        // Oracle TX with k=5 wallet, fresh VBC, sufficient stake, but scar_count=1.
        // Only the scar check should fire → OracleStakeScarred.
        use crate::types::Receipt;
        use crate::wallet_id::{generate_wallet_id_full, K_MAX, PROOF_TYPE_DMAP, WALLET_IDENTITY_KEY};

        // Generate k=5 wallet_id so OracleInsufficientK doesn't fire
        let k5_wid = generate_wallet_id_full("oracle@test.com", "42", &WALLET_IDENTITY_KEY, &test_pk(), K_MAX, PROOF_TYPE_DMAP)
            .expect("k=5 wallet_id");

        let mut tx = create_test_transaction();
        tx.epoch = 50_000;
        tx.amount = 0;
        tx.sender_wallet_id = k5_wid.clone();
        tx.receiver_wallet_id = k5_wid; // oracle = self-payout
        let living_sig = crate::oracle::living_signature(&tx.sender_wallet_id);
        tx.oracle_claim = Some(crate::types::OracleClaimData {
            platform_url: "https://foldingathome.org".into(),
            user_id: 1,
            username: format!("user_{}", living_sig),
            credit_total: 100_000,
            credit_delta: 10_000,
            payout_amount: 0,
            zktls_proof: None,
        });
        let mut inputs = create_test_inputs(tx);
        // §15: anchor prev_receipt.state_hash to the default test current_state
        // (pk=test_signing_key, balance=100_000_000_000, seq=0). Test wants
        // to assert OracleStakeScarred, not StateNotAnchored.
        let anchored_sh = crate::crypto::compute_state_hash(
            &test_signing_key().verifying_key().to_bytes().to_vec(),
            100_000_000_000u64, 0u64, 0, 0, 0, 0, &crate::types::WalletFormat::CURRENT);
        // Fresh VBC (age=100 ticks, well within 24h)
        let fresh_witness = make_witness_with_vbc_age(50_000 - 100);
        inputs.prev_receipts = vec![Receipt {
            oods_flag: None,
            confidence_index: None,
            sender_state: None,
            txid: [0u8; 32], state_hash: anchored_sh, produced_state_id: [0u8; 32],
            new_wallet_seq: 0, commitment_hash: [0u8; 32], sdid: [0u8; 32],
            lineage_hash: [0u8; 32], core_version: String::new(), core_id: [0u8; 32],
            witness_sigs: vec![fresh_witness], epoch: 0, fact_proof: None,
            required_k: 3,
            receipt_commitment: [0u8; 32],
            fee_breakdown: Vec::new(),
            is_dev_class: false,
        }];
        inputs.nabla_stake_proof = Some(crate::types::NablaStakeProof {
            balance: crate::oracle::ORACLE_MIN_STAKE + 1, // sufficient
            scar_count: 1, // scarred — only failing condition
            required_k: 3,
            wallet_pk: [0u8; 32],
            receipt_signatures: vec![],
            receipt_state_id: [0u8; 32],
        });
        let result = validate_transaction(&inputs).unwrap();
        assert_eq!(result.result, ValidationResult::Reject);
        assert_eq!(result.rejection_reason, Some(ValidationError::OracleStakeScarred),
            "Oracle TX with scarred stake must be rejected with OracleStakeScarred specifically");
    }

