    // ════════════════════════════════════════════════════════════════
    // Genesis 3-year lockup tests (White Paper §2.10.1)
    // ════════════════════════════════════════════════════════════════

    #[test]
    fn test_genesis_lockup_blocks_send() {
        // When wallet_ids are configured and the lock start > 0,
        // SEND transactions during the lockup period must be rejected.
        let lock_start = crate::genesis_integrity::GENESIS_STAKE_LOCK_START_SECS;
        if lock_start == 0 {
            return; // No lock start set
        }
        let lockup_end = lock_start + protocol_gen::LOCKUP_SECONDS;
        let locked_id = protocol_gen::GENESIS_LOCKUP_WALLET_IDS.iter()
            .find(|id| !id.is_empty());
        if locked_id.is_none() {
            return; // No wallet IDs configured yet
        }
        let locked_id = locked_id.unwrap();

        let mut tx = create_test_transaction();
        tx.sender_wallet_id = locked_id.to_string();
        tx.epoch = lockup_end - 1; // one second before lockup expires

        let inputs = create_test_inputs(tx);
        let result = validate_transaction(&inputs).unwrap();
        // This test was DORMANT until 2026-09-08 (the list was empty) and first
        // ran when §6c populated it. A hermetic test holds no genesis key, so the
        // listed id is not pk-bound to the test key and the sender-id binding
        // refuses the transaction BEFORE the lock is reached — the right order:
        // a stranger cannot borrow a genesis id to probe the lock. The lock's own
        // logic is exercised by `test_genesis_lockup_logic_direct`; with a real
        // genesis key the reason would be `GenesisStakeLocked`.
        //
        // ⚠ 2026-09-20 (two-label dev model, FactClassIsolation preamble point 0):
        // `is_dev_wallet` now matches `@axiom` too, and the genesis stake ids in
        // `genesis_lockup_wallets.txt` are ALL `@axiom` — so a listed id is now
        // DEV and its send to the real `receiver@test.com` is refused at R1
        // (`DomainMismatch`) BEFORE the sender-id/lockup gate. The send is still
        // blocked (that is what this test proves), just at the class gate.
        // ‼ THE REAL FIX is at the GENESIS CEREMONY: genesis validators must use
        // REAL domains (validators are real accounts — no dev VBC). Until that
        // migration, `@axiom` genesis ids read as dev; DomainMismatch is accepted
        // here as a valid block. See `feedback_dev_and_real_fully_isolated_two_domains`.
        assert!(
            matches!(result.rejection_reason,
                     Some(ValidationError::SenderWalletIdMismatch)
                     | Some(ValidationError::GenesisStakeLocked)
                     | Some(ValidationError::DomainMismatch)),
            "a listed genesis stake id must never send during the lockup — got {:?}",
            result.rejection_reason
        );
    }

    #[test]
    fn test_genesis_lockup_allows_after_expiry() {
        // After lockup_end, genesis wallet may send normally.
        let lock_start = crate::genesis_integrity::GENESIS_STAKE_LOCK_START_SECS;
        if lock_start == 0 {
            return;
        }
        let lockup_end = lock_start + protocol_gen::LOCKUP_SECONDS;
        let locked_id = protocol_gen::GENESIS_LOCKUP_WALLET_IDS.iter()
            .find(|id| !id.is_empty());
        if locked_id.is_none() {
            return;
        }
        let locked_id = locked_id.unwrap();

        let mut tx = create_test_transaction();
        tx.sender_wallet_id = locked_id.to_string();
        tx.epoch = lockup_end + 1; // one second after lockup expires

        let inputs = create_test_inputs(tx);
        let result = validate_transaction(&inputs).unwrap();
        assert_ne!(result.rejection_reason, Some(ValidationError::GenesisStakeLocked),
            "Genesis wallet must be unlocked after lockup expiry");
    }

    /// Direct test that exercises lockup logic regardless of wallet configuration.
    /// Verifies the check logic works with the real GENESIS_STAKE_LOCK_START_SECS.
    #[test]
    fn test_genesis_lockup_logic_direct() {
        let lock_start = crate::genesis_integrity::GENESIS_STAKE_LOCK_START_SECS;
        // The lock start is whatever the G1 ceremony baked (2026-03-19 on the dev
        // tree). It used to be pinned here as 1_773_878_400, which made this
        // test fail by construction after ANY real ceremony (2026-09-11
        // rehearsal 3, handoff §18.10). Assert its SHAPE: a UTC midnight in
        // the protocol's era. (Decoupled 2026-09-20 from GENESIS_NEWS_ANCHOR.)
        assert!(lock_start >= 1_773_878_400, "GENESIS_STAKE_LOCK_START_SECS predates the protocol (dev value 2026-03-19)");
        assert_eq!(lock_start % 86_400, 0, "GENESIS_STAKE_LOCK_START_SECS must be 00:00 UTC of the launch date");

        let lockup_secs: u64 = 94_608_000; // 3 years
        let lockup_end = lock_start + lockup_secs;
        let locked_id = "locked@test/ABCD";

        // Case 1: During lockup — must reject
        let mut tx = create_test_transaction();
        tx.sender_wallet_id = locked_id.to_string();
        tx.epoch = lockup_end - 1;

        let should_block = !locked_id.is_empty()
            && tx.sender_wallet_id == locked_id
            && tx.epoch < lockup_end;
        assert!(should_block, "Lockup logic must detect locked wallet during lockup period");

        // Case 2: After lockup — must allow
        tx.epoch = lockup_end + 1;
        let should_block = !locked_id.is_empty()
            && tx.sender_wallet_id == locked_id
            && tx.epoch < lockup_end;
        assert!(!should_block, "Lockup logic must allow wallet after lockup expiry");

        // Case 3: Different wallet — must allow
        tx.sender_wallet_id = "other@test/WXYZ".to_string();
        tx.epoch = lockup_end - 1;
        let should_block = !locked_id.is_empty()
            && tx.sender_wallet_id == locked_id
            && tx.epoch < lockup_end;
        assert!(!should_block, "Lockup logic must not block non-genesis wallets");

        // Case 4: lock_start=0 — lockup not active (hypothetical, it is hardcoded)
        let zero_lock_start: u64 = 0;
        let active = zero_lock_start > 0 && lockup_secs > 0;
        assert!(!active, "Lockup must be inactive when lock_start=0");
    }

    // ================================================================
    // Sender wallet_id ownership verification tests (YPX-007 §2.1.1)
    //
    // Post-v2.11.16: sender_wallet_id is no longer locked to the value
    // from the first TX. Instead, any wallet_id derived from the sender's
    // public key is accepted (tier switching is allowed). The pk_bind
    // check prevents impersonation (using another wallet's wallet_id).
    // ================================================================

    fn test_pk() -> [u8; 32] {
        let sk = test_signing_key();
        let vk = ed25519_dalek::VerifyingKey::from(&sk);
        vk.to_bytes()
    }

    fn generate_wallet_id_with_tier(email: &str, salt: &str, pk: &[u8; 32], k: u8, pt: u8) -> crate::CoreResult<String> {
        crate::wallet_id::generate_wallet_id_full(
            email, salt, &crate::wallet_id::WALLET_IDENTITY_KEY, pk, k, pt,
        )
    }

    #[test]
    fn test_sender_wallet_id_mismatch_rejected() {
        // Sender claims a wallet_id derived from a DIFFERENT pk → rejected.
        let pk = test_pk();
        let own_wid = generate_wallet_id("alice@test.com", "42", &pk).unwrap();
        let other_pk = [0u8; 32]; // different pk
        let spoofed_wid = generate_wallet_id("bob@test.com", "42", &other_pk).unwrap();

        let mut tx = create_test_transaction();
        tx.sender_wallet_id = spoofed_wid; // Attacker claims bob's wallet_id
        tx.wallet_seq = 1;
        tx.amount = 500_000;

        let mut inputs = create_test_inputs(tx);
        inputs.current_state = Some(WalletState {
            wall_clock_lock: 0,
            emission_claimed_epoch: 0,
            stake_floor_until: 0, wallet_format: crate::types::WalletFormat::CURRENT,
            public_key: pk.to_vec(),
            balance: 1_000_000,
            wallet_seq: 0,
            state_id: [0u8; 32],
            auth_hash: None,
            wallet_id: Some(own_wid),
            group_members: None, hibernation_until: 0,
        });

        let result = validate_transaction(&inputs).unwrap();
        assert_eq!(result.rejection_reason, Some(ValidationError::SenderWalletIdMismatch),
            "TX with spoofed sender_wallet_id (different pk) must be rejected");
    }

