    #[test]
    fn test_sender_wallet_id_prevents_lockup_bypass() {
        // Genesis lockup bypass attack: attacker changes sender_wallet_id to dodge lockup.
        // With identity binding, the mismatch is caught BEFORE lockup check.
        let genesis_wid = "validator_alpha@axiom/00000042".to_string();
        let fake_wid = "attacker@evil.com/deadbeef".to_string();

        let mut tx = create_test_transaction();
        tx.sender_wallet_id = fake_wid; // Try to dodge lockup
        tx.wallet_seq = 1;
        tx.amount = 500_000;

        let mut inputs = create_test_inputs(tx);
        inputs.current_state = Some(WalletState {
            wall_clock_lock: 0,
            emission_claimed_epoch: 0,
            stake_floor_until: 0, wallet_format: crate::types::WalletFormat::CURRENT,
            public_key: vec![0u8; 32],
            balance: 1_000_000,
            wallet_seq: 0,
            state_id: [0u8; 32],
            auth_hash: None,
            wallet_id: Some(genesis_wid), // Bound to genesis identity
            group_members: None, hibernation_until: 0,
        });

        let result = validate_transaction(&inputs).unwrap();
        assert_eq!(result.rejection_reason, Some(ValidationError::SenderWalletIdMismatch),
            "Genesis lockup bypass via wallet_id spoofing must be rejected");
    }

    #[test]
    fn test_genesis_pk_locked_even_with_wallet_id_none() {
        // Core-enforced: a GENESIS STAKE KEY is locked even on a first TX,
        // regardless of the sender_wallet_id it claims — and the lock is checked
        // BEFORE the signature, so a stranger cannot even probe it.
        //
        // ⚠ Until 2026-09-08 this used `GENESIS_VALIDATORS[0]` — a SPHINCS+ key —
        // as the Ed25519 `client_pk`, and passed only because the production
        // branch compared exactly that impossible pair (RULE 3 shape 1: the
        // test encoded the ghost). The real identity is `GENESIS_STAKE_WALLET_PKS`
        // (§6c), the Ed25519 keys the G1 ceremony lists.
        use crate::validation::protocol_gen::GENESIS_STAKE_WALLET_PKS;

        let lock_start = crate::genesis_integrity::GENESIS_STAKE_LOCK_START_SECS;
        let lockup_secs = protocol_gen::LOCKUP_SECONDS;

        // Only test if lockup is configured (non-zero lock start and lockup)
        if lock_start == 0 || lockup_secs == 0 || GENESIS_STAKE_WALLET_PKS.is_empty() {
            return; // Skip in builds with no lockup / no genesis list configured
        }

        let genesis_pk = GENESIS_STAKE_WALLET_PKS[0].to_vec();
        let genesis_pk_arr: [u8; 32] = genesis_pk[..32].try_into().unwrap();
        let valid_wid = generate_wallet_id("attacker@evil.com", "42", &genesis_pk_arr).unwrap();

        let mut tx = create_test_transaction();
        tx.client_pk = genesis_pk.clone();
        tx.sender_wallet_id = valid_wid; // Valid pk_bind, but genesis pk → locked
        tx.wallet_seq = 1;
        tx.amount = 500_000;
        tx.epoch = lock_start + 1; // During lockup period

        let mut inputs = create_test_inputs(tx);
        inputs.current_state = Some(WalletState {
            wall_clock_lock: 0,
            emission_claimed_epoch: 0,
            stake_floor_until: 0, wallet_format: crate::types::WalletFormat::CURRENT,
            public_key: genesis_pk,
            balance: 1_000_000,
            wallet_seq: 0,
            state_id: [0u8; 32],
            auth_hash: None,
            wallet_id: None, // First TX — not yet bound
            group_members: None, hibernation_until: 0,
        });

        let result = validate_transaction(&inputs).unwrap();
        assert_eq!(result.rejection_reason, Some(ValidationError::GenesisStakeLocked),
            "Genesis validator PK must be locked even with wallet_id=None (pk-based enforcement)");
    }

    /// The 3-year genesis stake lock must RELEASE at lockup_end so a genesis
    /// validator can MOVE its stake afterwards (economics: the 10 bootstrap
    /// validators "retire at will" once the lock expires; White Paper §2.10.1).
    /// Pins the release BOUNDARY off the lock's own key,
    /// `GENESIS_STAKE_LOCK_START_SECS` (decoupled 2026-09-20 from the fair-launch
    /// anchor) — the property that had NO coverage before (2026-09-20): the only
    /// prior "after expiry" test asserted the absence of the lock rejection with a
    /// non-genesis id that could never reach the gate.
    ///
    /// ⚠ A hermetic unit test cannot assert full Accept + debit: the genesis
    /// PRIVATE key is not available to sign, so past the lock the tx stops at
    /// signature verification, not the lock. What this proves is exactly the lock's
    /// job — LOCKED one second before expiry, NOT blocked by the lock at/after it.
    /// The literal signed move (Accept, balance falls) needs the on-disk genesis
    /// key + a forged post-lock epoch — C-tier gate `stake.genesis_lock_release`.
    #[test]
    fn test_genesis_stake_lock_releases_at_expiry() {
        use crate::validation::protocol_gen::GENESIS_STAKE_WALLET_PKS;
        let lock_start = crate::genesis_integrity::GENESIS_STAKE_LOCK_START_SECS;
        let lockup_secs = protocol_gen::LOCKUP_SECONDS;
        if lock_start == 0 || lockup_secs == 0 || GENESIS_STAKE_WALLET_PKS.is_empty() {
            return; // no lockup / no genesis list configured in this build
        }
        let lockup_end = lock_start + lockup_secs;
        let genesis_pk = GENESIS_STAKE_WALLET_PKS[0].to_vec();
        let genesis_pk_arr: [u8; 32] = genesis_pk[..32].try_into().unwrap();
        // A REAL-class sender id pk-bound to the genesis key (so the pk-layer lock
        // is the gate under test, not the class R1 / sender-id gates).
        let wid = generate_wallet_id("mover@example.com", "42", &genesis_pk_arr).unwrap();

        let probe = |epoch: u64| -> Option<ValidationError> {
            let mut tx = create_test_transaction();
            tx.client_pk = genesis_pk.clone();
            tx.sender_wallet_id = wid.clone();
            tx.wallet_seq = 1;
            tx.amount = 500_000;
            tx.epoch = epoch;
            let mut inputs = create_test_inputs(tx);
            inputs.current_state = Some(WalletState {
                wall_clock_lock: 0,
                emission_claimed_epoch: 0,
                stake_floor_until: 0, wallet_format: crate::types::WalletFormat::CURRENT,
                public_key: genesis_pk.clone(),
                balance: 1_000_000,
                wallet_seq: 0,
                state_id: [0u8; 32],
                auth_hash: None,
                wallet_id: None, // first TX — not yet bound
                group_members: None, hibernation_until: 0,
            });
            validate_transaction(&inputs).unwrap().rejection_reason
        };

        // one second BEFORE expiry — the stake is LOCKED (pk-layer enforcement).
        assert_eq!(probe(lockup_end - 1), Some(ValidationError::GenesisStakeLocked),
            "genesis stake must be LOCKED one second before lockup_end");
        // AT expiry — released. The gate is `tx.epoch < lock_start + lockup_secs`,
        // so `epoch == lockup_end` is already outside it.
        assert_ne!(probe(lockup_end), Some(ValidationError::GenesisStakeLocked),
            "genesis stake must RELEASE at lockup_end (tx.epoch < end is false)");
        // AFTER expiry — stays released: the lock no longer blocks the move.
        assert_ne!(probe(lockup_end + 1), Some(ValidationError::GenesisStakeLocked),
            "genesis stake must stay released after lockup_end — the stake can move");
    }

    // ========================================================================
    // YPX-015 §2.9: State_id check — cross-state double-spend prevention
    // These tests PROVE the current state_id check prevents an attack where
    // an attacker mixes validators with different state views.
    // If anyone relaxes the state_id check, these tests MUST fail.
    // ========================================================================

    /// State_id mismatch MUST be rejected — prevents cross-state double-spend.
    #[test]
    fn test_state_id_mismatch_rejected() {
        let mut tx = create_test_transaction();
        tx.consumed_state_id = [0xBB; 32];
        let sk = test_signing_key();
        let signing_msg = compute_signing_message(&tx);
        use ed25519_dalek::Signer;
        tx.client_sig = sk.sign(&signing_msg).to_bytes().to_vec();

        let mut inputs = create_test_inputs(tx);
        inputs.current_state = Some(WalletState {
            wall_clock_lock: 0,
            emission_claimed_epoch: 0,
            stake_floor_until: 0, wallet_format: crate::types::WalletFormat::CURRENT,
            public_key: inputs.transaction.client_pk.clone(),
            balance: 100_000_000,
            wallet_seq: 0,
            state_id: [0xAA; 32],
            auth_hash: None,
            wallet_id: None,
            group_members: None, hibernation_until: 0,
        });

        let result = validate_transaction(&inputs).unwrap();
        assert!(result.rejection_reason.is_some(),
            "State_id mismatch MUST be rejected — cross-state double-spend prevention");
    }

    /// Same wallet_seq = replay MUST be rejected.
