    /// Cross-state attack: consumed=B sent to validator with stored=C.
    /// MUST be rejected. See YPX-015 §2.9 for full attack scenario.
    #[test]
    fn test_cross_state_attack_prevented() {
        let sk = test_signing_key();
        let vk = ed25519_dalek::VerifyingKey::from(&sk);
        let pk_bytes = vk.to_bytes();
        let receiver = generate_wallet_id("recv@test.com", "42", &test_pk()).unwrap();

        let mut tx = Transaction {
            consumed_state_id: [0xBB; 32], // state B from partial witness
            client_pk: pk_bytes.to_vec(),
            sender_wallet_id: String::new(),
            wallet_seq: 3,
            receiver_wallet_id: receiver,
            receiver_address: None,
            amount: 500_001,
            reference: "cross-state-attack".into(),
            nonce: 999, epoch: 1,
            client_sig: vec![0u8; 64],
            scar_passcode: None,
            burn_target_tx_id: None,
            recall_target_tx_id: None,
            required_k: 0, proof_type: 0,
            oracle_claim: None, core_version: String::new(), core_id: [0u8; 32],
            kind: TxKind::Normal,
        };
        use ed25519_dalek::Signer;
        tx.client_sig = sk.sign(&compute_signing_message(&tx)).to_bytes().to_vec();

        let mut inputs = create_test_inputs(tx);
        inputs.current_state = Some(WalletState {
            wall_clock_lock: 0,
            emission_claimed_epoch: 0,
            stake_floor_until: 0, wallet_format: crate::types::WalletFormat::CURRENT,
            public_key: pk_bytes.to_vec(),
            balance: 20_000_000,
            wallet_seq: 2,
            state_id: [0xCC; 32], // state C — NOT B
            auth_hash: None,
            wallet_id: None,
            group_members: None, hibernation_until: 0,
        });

        let result = validate_transaction(&inputs).unwrap();
        assert!(result.rejection_reason.is_some(),
            "Cross-state attack MUST be rejected. consumed=B but stored=C. \
             Without this check, attacker extracts 175 from 100-atom wallet. \
             See YPX-015 §2.9.");
    }

    // ────────────────────────────────────────────────────────────────────
    // KI#257 (RULED 2026-10-02): `verify_state_id_chain` runs for heals.
    //   ~~YPX-018 heal-forward (v2.11.15-beta4): the chain check is skipped
    //   when `tx.is_heal() == true`~~ — that skip let a heal consume a
    //   half-signed (sub-quorum) state carrying a send's debit.
    //
    //   Test 1: the old heal-forward shape (committer stored the partial
    //   X_pending, the last full-quorum receipt produced X_prev) is REFUSED
    //   at Step 1b even though stored == consumed.
    //   Test 2: a heal whose consumed state is not the validator's stored
    //   state is refused at Step 1 (`verify_state_id_valid`), first.
    // ────────────────────────────────────────────────────────────────────

    /// The old heal-forward: `tx.consumed_state_id == stored.state_id`
    /// (committer path) but `!= last_receipt.produced_state_id` (no
    /// full-quorum receipt anchors it) → `InvalidStateId` (KI#257).
    /// MUTATION (2026-10-03): restore `&& !tx.is_heal()` on Step 1b → RED.
    #[test]
    fn test_is_heal_chain_check_refuses_a_partial_commit_state_ki257() {
        use ed25519_dalek::Signer;

        // Committer stored the partial-commit state X_pending at wseq=1.
        let x_pending = [0xEE; 32];
        // Pre-partial state X_prev was the produced_state_id of the last
        // successful TX. The wallet's last_receipt still points at this —
        // that's what a normal chain check would require us to consume.
        let x_prev = [0x11; 32];

        // Build a TX_HEAL that consumes X_pending (the poisoned state)
        // with wseq = 2 (committer stored wseq=1, heal advances by 1).
        let mut tx = create_test_transaction();
        tx.consumed_state_id = x_pending;
        tx.wallet_seq = 2;
        tx.kind = crate::types::TxKind::Heal;
        // Sender == receiver (self-send invariant for heal)
        tx.receiver_wallet_id = generate_wallet_id("receiver@test.com", "42", &test_pk())
            .expect("wallet_id");
        tx.sender_wallet_id = tx.receiver_wallet_id.clone();
        // Re-sign over the heal-bound signing message.
        let sk = test_signing_key();
        tx.client_sig = sk.sign(&compute_signing_message(&tx)).to_bytes().to_vec();

        let mut inputs = create_test_inputs(tx);
        // Committer's stored state matches the heal's consumed state.
        inputs.current_state = Some(WalletState {
            wall_clock_lock: 0,
            emission_claimed_epoch: 0,
            stake_floor_until: 0, wallet_format: crate::types::WalletFormat::CURRENT,
            public_key: inputs.transaction.client_pk.clone(),
            balance: 50_000_000,
            wallet_seq: 1,
            state_id: x_pending,
            auth_hash: None,
            wallet_id: None,
            group_members: None, hibernation_until: 0,
        });
        // prev_receipts breaks the chain — last_receipt's produced_state_id
        // is X_prev, not X_pending: X_pending has no full-quorum receipt.
        let (pk1, sig1) = test_validator_sig(&[0x01; 32], &[0xCC; 32]);
        let (pk2, sig2) = test_validator_sig(&[0x02; 32], &[0xCC; 32]);
        let (pk3, sig3) = test_validator_sig(&[0x03; 32], &[0xCC; 32]);
        inputs.prev_receipts = vec![Receipt {
            oods_flag: None,
            confidence_index: None,
            sender_state: None,
            txid: [0u8; 32],
            state_hash: [0u8; 32],
            produced_state_id: x_prev, // ← intentionally ≠ x_pending
            new_wallet_seq: 1,
            commitment_hash: [0xCC; 32],
            sdid: crate::types::genesis_sdid(),
            lineage_hash: crate::types::genesis_lineage_hash(),
            witness_sigs: vec![
                make_test_witness(pk1, sig1),
                make_test_witness(pk2, sig2),
                make_test_witness(pk3, sig3),
            ],
            core_version: String::new(),
            core_id: [0u8; 32],
            epoch: 1,
            fact_proof: None,
            required_k: 3,
            receipt_commitment: [0u8; 32],
            fee_breakdown: Vec::new(),
            is_dev_class: false,
        }];

        let result = validate_transaction(&inputs).unwrap();
        assert_eq!(
            result.rejection_reason,
            Some(ValidationError::InvalidStateId),
            "a heal must consume the last full-quorum receipt's state (KI#257). Got {:?}",
            result.rejection_reason
        );
    }

    /// Malicious heal: `tx.is_heal() = true` but `stored.state_id != consumed`.
    /// `verify_state_id_valid` (Step 1) rejects with `InvalidStateId` before
    /// the chain check (Step 1b) is reached.
    #[test]
    fn test_is_heal_still_rejects_when_stored_mismatches_consumed() {
        use ed25519_dalek::Signer;
        let x_rogue = [0xDD; 32];
        let x_stored = [0xAA; 32];

        let mut tx = create_test_transaction();
        tx.consumed_state_id = x_rogue; // client claims to heal from X_rogue
        tx.wallet_seq = 2;
        tx.kind = crate::types::TxKind::Heal;
        tx.receiver_wallet_id = generate_wallet_id("receiver@test.com", "42", &test_pk())
            .expect("wallet_id");
        tx.sender_wallet_id = tx.receiver_wallet_id.clone();
        let sk = test_signing_key();
        tx.client_sig = sk.sign(&compute_signing_message(&tx)).to_bytes().to_vec();

        let mut inputs = create_test_inputs(tx);
        // Honest validator is stored at X_stored, not X_rogue.
        inputs.current_state = Some(WalletState {
            wall_clock_lock: 0,
            emission_claimed_epoch: 0,
            stake_floor_until: 0, wallet_format: crate::types::WalletFormat::CURRENT,
            public_key: inputs.transaction.client_pk.clone(),
            balance: 50_000_000,
            wallet_seq: 1,
            state_id: x_stored, // ← does NOT match the heal's consumed
            auth_hash: None,
            wallet_id: None,
            group_members: None, hibernation_until: 0,
        });
        // Populate prev_receipts so we reach verify_state_id_valid (not
        // blocked earlier by the `MissingPrevReceipts` gate at ~line 207).
        // The receipt's produced_state_id is intentionally *different* from
        // both x_stored and x_rogue; Step 1 fires first, which is what is
        // under test (Step 1b would refuse too since KI#257).
        let (pk1, sig1) = test_validator_sig(&[0x01; 32], &[0xCC; 32]);
        let (pk2, sig2) = test_validator_sig(&[0x02; 32], &[0xCC; 32]);
        let (pk3, sig3) = test_validator_sig(&[0x03; 32], &[0xCC; 32]);
        inputs.prev_receipts = vec![Receipt {
            oods_flag: None,
            confidence_index: None,
            sender_state: None,
            txid: [0u8; 32],
            state_hash: [0u8; 32],
            produced_state_id: [0x11; 32],
            new_wallet_seq: 1,
            commitment_hash: [0xCC; 32],
            sdid: crate::types::genesis_sdid(),
            lineage_hash: crate::types::genesis_lineage_hash(),
            witness_sigs: vec![
                make_test_witness(pk1, sig1),
                make_test_witness(pk2, sig2),
                make_test_witness(pk3, sig3),
            ],
            core_version: String::new(),
            core_id: [0u8; 32],
            epoch: 1,
            fact_proof: None,
            required_k: 3,
            receipt_commitment: [0u8; 32],
            fee_breakdown: Vec::new(),
            is_dev_class: false,
        }];

        let result = validate_transaction(&inputs).unwrap();
        assert_eq!(
            result.rejection_reason,
            Some(ValidationError::InvalidStateId),
            "is_heal=true MUST still be caught by verify_state_id_valid \
             when the validator's stored state does not match the claimed \
             consumed_state_id. Without this, skipping the chain check would \
             open a rollback double-spend hole. Got {:?}",
            result.rejection_reason
        );
    }

    // ────────────────────────────────────────────────────────────────────
    // CL2_PREFILTER (ANTIE gateway) tests — CLAUDE.md §8.
    //
    // ANTIE pre-executes Core with `current_state = None` so it never
    // synthesizes a stored WalletState. The CL2_PREFILTER mode must:
    //   1. ACCEPT a TX_HEAL with no stored state — Lambda's CL2 pass owns the
    //      real stored-state check. This is the regression that motivated
    //      CL2_PREFILTER (the pre-fix tautological WalletState pattern caused
    //      `InvalidStateId` rejects at the gateway). Since KI#257 the heal must
    //      consume its last full-quorum receipt's state, which the gateway
    //      checks from the request alone (Step 1b needs no stored state).
    //   2. Still REJECT structural failures (bad signature, dust amount,
    //      Ark policy violations, oracle policy violations, etc.) that can
    //      be checked from the request alone.
    //   3. NOT require a stored WalletState — `current_state = None` is the
    //      only honest input ANTIE can supply, and it must not produce
    //      `MissingWalletState`.
    // ────────────────────────────────────────────────────────────────────

    /// Regression: CL2_PREFILTER must ACCEPT a TX_HEAL with no stored state.
    /// Pre-fix this same TX through `CoreLogicMode::CL2` with a tautological
    /// WalletState (state_id=consumed) accidentally passed; with state=None
    /// it would have hit `MissingWalletState` at the balance check. The
    /// fix is the new mode + the `is_prefilter && state.is_none()` gates
    /// inside `validate_transaction`.
    #[test]
    fn test_cl2_prefilter_accepts_tx_heal_with_no_state() {
        use ed25519_dalek::Signer;

        let x_prev = [0x11; 32];

        let mut tx = create_test_transaction();
        // The production heal shape: consume the anchored tip (KI#257).
        tx.consumed_state_id = x_prev;
        tx.wallet_seq = 2;
        tx.kind = crate::types::TxKind::Heal;
        tx.receiver_wallet_id = generate_wallet_id("receiver@test.com", "42", &test_pk())
            .expect("wallet_id");
        tx.sender_wallet_id = tx.receiver_wallet_id.clone();
        let sk = test_signing_key();
        tx.client_sig = sk.sign(&compute_signing_message(&tx)).to_bytes().to_vec();

        let mut inputs = create_test_inputs(tx);
        inputs.mode = crate::CoreLogicMode::CL2_PREFILTER;
        // The defining property: ANTIE has NO stored state.
        inputs.current_state = None;

        // Carry the same prev_receipts the client would forward to a real
        // validator — the heal chains to its produced state (Step 1b).
        let (pk1, sig1) = test_validator_sig(&[0x01; 32], &[0xCC; 32]);
        let (pk2, sig2) = test_validator_sig(&[0x02; 32], &[0xCC; 32]);
        let (pk3, sig3) = test_validator_sig(&[0x03; 32], &[0xCC; 32]);
        inputs.prev_receipts = vec![Receipt {
            oods_flag: None,
            confidence_index: None,
            sender_state: None,
            txid: [0u8; 32],
            state_hash: [0u8; 32],
            produced_state_id: x_prev,
            new_wallet_seq: 1,
            commitment_hash: [0xCC; 32],
            sdid: crate::types::genesis_sdid(),
            lineage_hash: crate::types::genesis_lineage_hash(),
            witness_sigs: vec![
                make_test_witness(pk1, sig1),
                make_test_witness(pk2, sig2),
                make_test_witness(pk3, sig3),
            ],
            core_version: String::new(),
            core_id: [0u8; 32],
            epoch: 1,
            fact_proof: None,
            required_k: 3,
            receipt_commitment: [0u8; 32],
            fee_breakdown: Vec::new(),
            is_dev_class: false,
        }];

        let result = validate_transaction(&inputs).unwrap();
        assert_eq!(
            result.result, ValidationResult::Accept,
            "CL2_PREFILTER on TX_HEAL with state=None must Accept. Got reason={:?}",
            result.rejection_reason
        );
        // No stored state → no produced state hashes (Lambda's CL2 computes them).
        assert!(
            result.produced_state_id.is_none(),
            "CL2_PREFILTER must not synthesize produced_state_id without stored state"
        );
        assert!(
            result.new_state_hash.is_none(),
            "CL2_PREFILTER must not synthesize new_state_hash without stored state"
        );
        // commitment_hash IS computable from the request alone — keep it.
        assert!(
            result.commitment_hash.is_some(),
            "CL2_PREFILTER must still produce commitment_hash (request-only data)"
        );
    }

    /// CL2_PREFILTER must still reject a transaction with a bad client
    /// signature — the structural checks that don't need stored state
    /// are exactly the ones the gateway is responsible for.
    #[test]
    fn test_cl2_prefilter_still_rejects_bad_client_sig() {
        let mut tx = create_test_transaction();
        tx.amount = 1_000_000; // above dust
        // Receiver is a different person (different pk) so this isn't read as a
        // self-send under the pk-binding check (§10.3) before the sig check runs.
        tx.receiver_wallet_id = generate_wallet_id("receiver@test.com", "42", &[0x99u8; 32])
            .expect("wallet_id");
        tx.sender_wallet_id = generate_wallet_id("sender@test.com", "42", &test_pk())
            .expect("wallet_id");
        // Garbage signature — must reject regardless of state availability.
        tx.client_sig = vec![0xFF; 64];

        let mut inputs = create_test_inputs(tx);
        inputs.mode = crate::CoreLogicMode::CL2_PREFILTER;
        inputs.current_state = None;
        // First TX (wallet_seq=1): no prev_receipts required.

        let result = validate_transaction(&inputs).unwrap();
        assert_eq!(result.result, ValidationResult::Reject);
        assert_eq!(
            result.rejection_reason,
            Some(ValidationError::InvalidClientSignature),
            "Bad client sig must reject under CL2_PREFILTER. Got {:?}",
            result.rejection_reason
        );
    }

    /// CL2_PREFILTER must NOT return `MissingWalletState` when state is
    /// absent — that error meant "Lambda forgot to attach state", and
    /// under the new architecture ANTIE intentionally does not attach it.
    /// Confirms the `is_prefilter && state.is_none()` gates fire at all
    /// the right places.
    #[test]
    fn test_cl2_prefilter_never_returns_missing_wallet_state() {
        use ed25519_dalek::Signer;

        let mut tx = create_test_transaction();
        tx.wallet_seq = 1;
        tx.amount = 1_000_000;
        tx.receiver_wallet_id = generate_wallet_id("receiver@test.com", "42", &test_pk())
            .expect("wallet_id");
        tx.sender_wallet_id = generate_wallet_id("sender@test.com", "42", &test_pk())
            .expect("wallet_id");
        let sk = test_signing_key();
        tx.client_sig = sk.sign(&compute_signing_message(&tx)).to_bytes().to_vec();

        let mut inputs = create_test_inputs(tx);
        inputs.mode = crate::CoreLogicMode::CL2_PREFILTER;
        inputs.current_state = None;

        let result = validate_transaction(&inputs).unwrap();
        assert_ne!(
            result.rejection_reason,
            Some(ValidationError::MissingWalletState),
            "CL2_PREFILTER must never produce MissingWalletState. Got {:?}",
            result.rejection_reason
        );
    }

    // ────────────────────────────────────────────────────────────────────
    // Test helpers for the two YPX-018 heal-forward tests above. Mirror
    // the minimal-VBC pattern used by test_duplicate_witness_detected.
    // ────────────────────────────────────────────────────────────────────

    fn test_validator_sig(sk_seed: &[u8; 32], commitment: &[u8; 32]) -> (Vec<u8>, Vec<u8>) {
        use ed25519_dalek::{SigningKey as TestSk, Signer};
        let sk = TestSk::from_bytes(sk_seed);
        let pk = sk.verifying_key().to_bytes().to_vec();
        let sig = sk.sign(commitment).to_bytes().to_vec();
        (pk, sig)
    }

    fn make_test_witness(pk: Vec<u8>, sig: Vec<u8>) -> WitnessSig {
        let sphincs_pk = vec![0xAA; 32];
        let validator_id = *blake3::hash(&sphincs_pk).as_bytes();
        WitnessSig {
            validator_id,
            validator_pk: pk,
            vbc_bundle: Some(VBCProofBundle {
                target_vbc: VBC {
                    genesis_lineage: [0u8; 32],
                    network_size_baseline: 0,
                    baseline_tick: 0,
                    version: 0x09,
                    validator_id,
                    subject_pubkey_sphincs: sphincs_pk,
                    subject_pubkey_dilithium: vec![0u8; 1952],
                    subject_pubkey_ed25519: vec![0u8; 32],
                    pgp_fingerprint: vec![],
                    node_name: String::new(),
                    proof_cap: String::new(),
                    issued_at: 0,
                    expires_at: u64::MAX,
                    chain_depth: 0,
                    issuer_set: vec![],
                    signatures: vec![],
                    max_tx: 0,
                    founding_vbc_hash: [0u8; 32],
                    nabla_registration: None,
                },
                supporting_vbcs: vec![],
                candidacy_pulse: None, renewal_work_receipt: None,
            }),
            carrier_type: String::new(),
            carrier_address: String::new(),
            signature: sig,
            execution_proof: vec![],
            proof_type: 1,
            availability_attestation: None,
            validator_hints: vec![],
            fact_signature: None,
            checkpoint_sig: None,
            receipt_signature: None,
                receipt_commitment_sig: None,
                rate_bps: 0,
                slot_amount: 0,
        }
    }

    // ── validate_witnesses heal floor tests ───────────────────────────

    fn make_receipt_with_n_witnesses_and_k(n: usize, k: u8) -> Receipt {
        let witnesses: Vec<WitnessSig> = (0..n).map(|i| {
            let mut pk = vec![0u8; 32];
            pk[0] = i as u8;
            let sphincs_pk = vec![0xBB; 32];
            let validator_id = *blake3::hash(&sphincs_pk).as_bytes();
            WitnessSig {
                validator_id,
                validator_pk: pk,
                vbc_bundle: Some(VBCProofBundle {
                    target_vbc: VBC {
                        genesis_lineage: [0u8; 32],
                        network_size_baseline: 0,
                        baseline_tick: 0,
                        version: 0x09,
                        validator_id,
                        subject_pubkey_sphincs: sphincs_pk,
                        subject_pubkey_dilithium: vec![0u8; 1952],
                        subject_pubkey_ed25519: vec![0u8; 32],
                        pgp_fingerprint: vec![],
                        node_name: String::new(),
                        proof_cap: String::new(),
                        issued_at: 0,
                        expires_at: u64::MAX,
                        chain_depth: 0,
                        issuer_set: vec![],
                        signatures: vec![],
                        max_tx: 0,
                        founding_vbc_hash: [0u8; 32],
                        nabla_registration: None,
                    },
                    supporting_vbcs: vec![],
                    candidacy_pulse: None, renewal_work_receipt: None,
                }),
                carrier_type: String::new(),
                carrier_address: format!("validator{}@axiom", i),
                signature: vec![0u8; 64],
                execution_proof: vec![],
                proof_type: 1,
                availability_attestation: None,
                validator_hints: vec![],
                fact_signature: None,
                checkpoint_sig: None,
                receipt_signature: None,
                receipt_commitment_sig: None,
                rate_bps: 0,
                slot_amount: 0,
            }
        }).collect();

        Receipt {
            oods_flag: None,
            confidence_index: None,
            sender_state: None,
            txid: [0u8; 32],
            state_hash: [0u8; 32],
            produced_state_id: [1u8; 32],
            new_wallet_seq: 1,
            commitment_hash: [0x99u8; 32],
            witness_sigs: witnesses,
            epoch: 1000,
            lineage_hash: crate::types::genesis_lineage_hash(),
            fact_proof: None,
            core_version: String::new(),
            core_id: [0u8; 32],
            sdid: [0u8; 32],
            required_k: k,
            receipt_commitment: [0u8; 32],
            fee_breakdown: Vec::new(),
            is_dev_class: false,
        }
    }

    #[test]
    fn test_quorum_gate_heal_rejects_2sig_prev_receipt() {
        // QUORUM GATE (YP §17.1.2): no anchor below 3 witnesses, heal included.
        // The old sabr_overlap=2 heal exemption is gone — a 2-sig partial can never
        // anchor the next move (partial commits no longer exist under the quorum gate).
        let mut tx = create_test_transaction();
        tx.kind = crate::types::TxKind::Heal;
        let mut inputs = create_test_inputs(tx);
        inputs.prev_receipts = vec![make_receipt_with_n_witnesses_and_k(2, 3)];
        let result = validate_witnesses(&inputs);
        assert!(matches!(result, Err(ValidationError::InvalidVBCCount)),
            "quorum gate: heal with a 2-sig anchor must be rejected, got: {:?}", result);
    }

    #[test]
    fn test_heal_k3_rejects_1sig_prev_receipt() {
        // k=3, sabr_overlap(3)=2 → floor=2, sigs=1 → reject
        let mut tx = create_test_transaction();
        tx.kind = crate::types::TxKind::Heal;
        let mut inputs = create_test_inputs(tx);
        inputs.prev_receipts = vec![make_receipt_with_n_witnesses_and_k(1, 3)];
        let result = validate_witnesses(&inputs);
        assert!(matches!(result, Err(ValidationError::InvalidVBCCount)),
            "heal k=3 with 1 sig should reject (below sabr_overlap=2)");
    }

    /// SEC-04 (heal-floor guard, follow-up #3): a heal cannot qualify with
    /// fewer than `sabr_overlap(required_k)` overlapped witnesses. This is the
    /// count floor that pairs with the modes.rs `_`-arm overlap check, which
    /// FULL-VBC-verifies each of those `sabr_overlap` overlap sigs (Check 4) —
    /// so a heal whose overlap is fake-key/no-VBC witnesses cannot meet the
    /// floor (the no-VBC sigs fail Check 4 and don't count) and is rejected
    /// with SABRInsufficientOverlap on the value path. Here we lock the count
    /// floor for every tier; the full-VBC rejection itself is exercised by the
    /// existing CL2/CL5 overlap tests + the production overlap logic. Each row
    /// below is one-below `sabr_overlap(k)` → must reject.
    #[test]
    fn test_sec04_heal_floor_equals_sabr_overlap_per_tier() {
        for (k, floor) in [(3u8, 2usize), (4, 3), (5, 3)] {
            assert_eq!(crate::wallet_id::sabr_overlap(k) as usize, floor,
                "sabr_overlap({k}) must be {floor} — the heal floor SEC-04 depends on");
            // One witness below the floor → reject (can't heal-forward).
            let mut tx = create_test_transaction();
            tx.kind = crate::types::TxKind::Heal;
            let mut inputs = create_test_inputs(tx);
            inputs.prev_receipts = vec![make_receipt_with_n_witnesses_and_k(floor - 1, k)];
            assert!(
                matches!(validate_witnesses(&inputs), Err(ValidationError::InvalidVBCCount)),
                "heal k={k} with {} witnesses (below sabr_overlap={floor}) must reject",
                floor - 1,
            );
        }
    }

    /// YP §17.3.1.4 v2.19.0 (KI#150): an ANCHOR receipt is judged at its own
    /// `required_k` — heal included (the quorum gate has no heal exemption: a
    /// wallet's anchor is its last FULL-quorum receipt; the partial the heal
    /// recovers is never an anchor). Until 2026-09-12 this test asserted that a
    /// k=4 anchor with three witnesses passes — the constant-3 floor, not a rule.
    #[test]
    fn test_heal_k4_anchor_needs_its_own_k() {
        let mut tx = create_test_transaction();
        tx.kind = crate::types::TxKind::Heal;
        let mut inputs = create_test_inputs(tx);
        inputs.prev_receipts = vec![make_receipt_with_n_witnesses_and_k(3, 4)];
        assert!(matches!(validate_witnesses(&inputs), Err(ValidationError::InvalidVBCCount)),
            "heal k=4 with a 3-witness anchor must reject (anchor quorum = required_k = 4)");
        let mut tx = create_test_transaction();
        tx.kind = crate::types::TxKind::Heal;
        let mut inputs = create_test_inputs(tx);
        inputs.prev_receipts = vec![make_receipt_with_n_witnesses_and_k(4, 4)];
        let result = validate_witnesses(&inputs);
        assert!(!matches!(result, Err(ValidationError::InvalidVBCCount)),
            "heal k=4 with a 4-witness anchor must pass the count, got: {:?}", result);
    }

    #[test]
    fn test_heal_k4_rejects_2sig_prev_receipt() {
        // k=4, sabr_overlap(4)=3 → floor=3, sigs=2 → reject
        let mut tx = create_test_transaction();
        tx.kind = crate::types::TxKind::Heal;
        let mut inputs = create_test_inputs(tx);
        inputs.prev_receipts = vec![make_receipt_with_n_witnesses_and_k(2, 4)];
        let result = validate_witnesses(&inputs);
        assert!(matches!(result, Err(ValidationError::InvalidVBCCount)),
            "heal k=4 with 2 sigs should reject (below sabr_overlap=3)");
    }

