    /// Spec test 5: charge (k≥3 sender → k=0 receiver) is untouched — the k≥3
    /// sender keeps the absolute 3-floor it always had.
    #[test]
    fn k0_charge_unaffected() {
        let mut tx = create_test_transaction();
        tx.sender_wallet_id = anchor_purity_wallet_id("normal@test.com", crate::wallet_id::K_DEFAULT);
        tx.receiver_wallet_id = anchor_purity_wallet_id("arkreceiver@test.com", crate::wallet_id::K_ARK);
        let mut inputs = create_test_inputs(tx);
        inputs.my_validator_pk = Some(vec![0u8; 32]);
        inputs.prev_receipts = vec![make_receipt_with_n_witnesses_and_k(3, 3)];
        let ok = validate_witnesses(&inputs);
        assert!(!matches!(ok, Err(ValidationError::InvalidVBCCount)),
            "charge with a 3-witness anchor must pass the floor, got: {:?}", ok);
        inputs.prev_receipts = vec![make_receipt_with_n_witnesses_and_k(2, 3)];
        let bad = validate_witnesses(&inputs);
        assert!(matches!(bad, Err(ValidationError::InvalidVBCCount)),
            "charge with a 2-witness anchor must still reject, got: {:?}", bad);
    }

    // ── VBC lifecycle windows (AXIOM_DESIGN_ValidatorJoin.md §5.2) ──

    /// The three windows MUST stay ordered:
    ///     renewal_window > unusable_remaining > provisional_expiry
    ///
    /// Raise `unusable` above `renewal` and every validator on the mesh goes
    /// dark BEFORE it is allowed to renew — the exact stranding the design
    /// exists to prevent. This asserts it at build time so a bad register edit
    /// fails CI rather than the fleet.
    #[test]
    fn vbc_lifecycle_windows_are_ordered() {
        assert!(
            VBC_RENEWAL_WINDOW_SECS > VBC_UNUSABLE_REMAINING_SECS,
            "renewal window ({VBC_RENEWAL_WINDOW_SECS}) must exceed the unusable \
             threshold ({VBC_UNUSABLE_REMAINING_SECS}) — otherwise a validator \
             becomes unusable before it may renew, and is stranded",
        );
        assert!(
            PROVISIONAL_VBC_EXPIRY_SECS < VBC_UNUSABLE_REMAINING_SECS,
            "a provisional cert ({PROVISIONAL_VBC_EXPIRY_SECS}) must be shorter \
             than the unusable threshold ({VBC_UNUSABLE_REMAINING_SECS}) so it is \
             born unable to serve — no boundary case to argue",
        );
    }

    /// `vbc_is_provisional` in isolation — the predicate the two reliance-site
    /// gates share (`validate_witnesses`, CL5's per-cheque check).
    ///
    /// The property that matters is that it takes NO `now`. A provisional is
    /// provisional at the instant it is signed and still provisional a decade
    /// later, so a gate built on it can never invalidate a receipt that was
    /// honest when it was made. Every remaining-life alternative considered for
    /// these sites had that retroactive failure mode.
    #[test]
    fn vbc_is_provisional_reads_lifetime_and_honours_the_sentinel() {
        let issued = 1_700_000_000u64;

        // At the bound: exactly what execute_cl8 signs unstaked.
        assert!(vbc_is_provisional(issued, issued + PROVISIONAL_VBC_EXPIRY_SECS));
        // One second past it is a full cert — same boundary execute_cl8 uses,
        // so the issuing rule and the serving rule cannot disagree.
        assert!(!vbc_is_provisional(issued, issued + PROVISIONAL_VBC_EXPIRY_SECS + 1));
        // A year: obviously not provisional.
        assert!(!vbc_is_provisional(issued, issued + 365 * 24 * 3600));

        // The SENTINEL. `expires_at == 0` means "never expires" throughout the
        // VBC path; reading it as a zero-length lifetime would classify every
        // non-genesis cert (validator_setup.rs stamps 0) as provisional.
        assert!(!vbc_is_provisional(issued, 0),
            "expires_at == 0 is the never-expires sentinel — never a provisional");
        assert!(!vbc_is_provisional(0, 0));
        // Genesis certs carry u64::MAX and must be unaffected.
        assert!(!vbc_is_provisional(0, u64::MAX));

        // Inverted window (expires before issued) reads as provisional, i.e.
        // refused at a reliance site. Fails CLOSED, and execute_cl8 refuses to
        // sign one anyway.
        assert!(vbc_is_provisional(issued, issued - 1));

        // Time-invariance, stated as an assertion rather than a comment: the
        // answer for one cert is a single value, not a function of when it is
        // asked. This is what makes the gate non-retroactive.
        let (a, b) = (issued, issued + PROVISIONAL_VBC_EXPIRY_SECS);
        assert_eq!(vbc_is_provisional(a, b), vbc_is_provisional(a, b));
    }

    /// Serve/renew gating across the whole lifetime of a cert, in ticks.
    #[test]
    fn vbc_serve_and_renew_windows_behave() {
        let issued = 1_000_000u64;
        let expires = issued + 31_536_000; // 1 year

        // Fresh: serves, too early to renew.
        assert!(vbc_can_serve(expires, issued));
        assert!(!vbc_can_renew(expires, issued));

        // Inside the renewal window but still serving (the ~6-day band).
        let t = expires - VBC_RENEWAL_WINDOW_SECS + 1;
        assert!(vbc_can_serve(expires, t), "still serving early in the window");
        assert!(vbc_can_renew(expires, t));

        // Inside the unusable window: cannot serve, MUST still be able to renew
        // — otherwise the cert is stranded with no exit.
        let t = expires - VBC_UNUSABLE_REMAINING_SECS + 1;
        assert!(!vbc_can_serve(expires, t), "below the threshold it cannot serve");
        assert!(vbc_can_renew(expires, t), "the unusable band MUST still permit renewal");

        // Exactly at the threshold it still serves (>= is deliberate).
        let t = expires - VBC_UNUSABLE_REMAINING_SECS;
        assert!(vbc_can_serve(expires, t));

        // Expired: neither. This is what makes heritage loss real.
        assert!(!vbc_can_serve(expires, expires));
        assert!(!vbc_can_renew(expires, expires), "an EXPIRED cert is not renewable");
        assert!(!vbc_can_renew(expires, expires + 1));
    }

    /// A provisional cert is born unable to serve, and is renewable from
    /// issuance — that renewal (with a stake proof) is the promotion path.
    #[test]
    fn provisional_vbc_is_born_unusable_but_renewable() {
        let issued = 5_000_000u64;
        let expires = issued + PROVISIONAL_VBC_EXPIRY_SECS;
        assert!(!vbc_can_serve(expires, issued), "provisional must never serve");
        assert!(vbc_can_renew(expires, issued), "provisional must be promotable immediately");
    }

    /// FACT class isolation Rule R1, end-to-end through `validate_transaction`:
    /// a cross-class TX (public sender, dev receiver) is rejected with
    /// `E_DOMAIN_MISMATCH` before any other validation pass runs.
    #[test]
    fn test_r1_cross_class_tx_rejected_by_validate_transaction() {
        let mut tx = create_test_transaction();
        // create_test_transaction's receiver is `receiver@test.com` (public);
        // the sender wallet_id is left blank by default. Set the sender
        // to a properly-bound public wallet_id (matches the test's pk),
        // and re-target the receiver to `@axiom.internal` (dev). The
        // helper inserts at Step -0.6, ahead of the pk_bind check.
        let sk = test_signing_key();
        let vk = ed25519_dalek::VerifyingKey::from(&sk);
        let pk_bytes = vk.to_bytes();
        tx.sender_wallet_id = crate::wallet_id::generate_wallet_id(
            "alice@example.com", "42", &pk_bytes,
        ).unwrap();
        tx.receiver_wallet_id = crate::wallet_id::generate_wallet_id(
            "developer@axiom.internal", "42", &[0xC0u8; 32],
        ).unwrap();
        // Re-sign — sender_wallet_id changed.
        use ed25519_dalek::Signer;
        let signing_msg = compute_signing_message(&tx);
        tx.client_sig = sk.sign(&signing_msg).to_bytes().to_vec();

        let inputs = create_test_inputs(tx);
        let result = validate_transaction(&inputs).unwrap();
        assert_eq!(
            result.rejection_reason,
            Some(ValidationError::DomainMismatch),
            "cross-class TX must surface E_DOMAIN_MISMATCH",
        );
    }

    // ───────────────────────────────────────────────────────────────────
    // validate_fee_breakdown — YP §19.6 amendment cap rules
    // ───────────────────────────────────────────────────────────────────

    fn make_fee_share(amount: u64) -> FeeShare {
        FeeShare { validator_id: [0u8; 32], amount }
    }

    #[test]
    fn fee_breakdown_empty_is_ok() {
        // Heal / genesis / zero-rate paths emit empty breakdowns. Always Ok.
        assert!(validate_fee_breakdown(1_000_000, &[]).is_ok());
        assert!(validate_fee_breakdown(0, &[]).is_ok());
    }

    #[test]
    fn fee_breakdown_at_per_validator_cap_passes() {
        // amount = 1_000_000 atoms, cap per validator = 30 bps = 3000 atoms.
        // Exactly 3000 per slot must pass.
        let breakdown = vec![make_fee_share(3000), make_fee_share(3000), make_fee_share(3000)];
        assert!(validate_fee_breakdown(1_000_000, &breakdown).is_ok());
    }

    #[test]
    fn fee_breakdown_one_atom_over_per_validator_cap_rejects() {
        // 3001 atoms in a single slot exceeds 30 bps of 1_000_000.
        let breakdown = vec![make_fee_share(3001)];
        assert_eq!(
            validate_fee_breakdown(1_000_000, &breakdown),
            Err(ValidationError::FeeExceedsValidatorCap),
        );
    }

    #[test]
    fn fee_breakdown_at_aggregate_cap_passes() {
        // 3 slots × 3000 atoms = 9000 = 90 bps of 1_000_000 = aggregate cap.
        let breakdown = vec![make_fee_share(3000), make_fee_share(3000), make_fee_share(3000)];
        assert!(validate_fee_breakdown(1_000_000, &breakdown).is_ok());
    }

    #[test]
    fn fee_breakdown_aggregate_branch_unreachable_under_k_scaling() {
        // After k-scaling (2026-06-03 protocol fix): aggregate cap =
        // k × MAX_VALIDATOR_FEE_BPS × amount / FEE_BPS_DIVISOR, where k is
        // the number of fee_breakdown entries. So `sum(slots) ≤
        // k × per_validator_cap` is implied by `each slot ≤ per_validator_cap`.
        // The aggregate-cap rejection branch is therefore structurally
        // unreachable unless a slot exceeds the per-validator cap (which
        // the per-slot check rejects first). This test pins that property
        // by enumerating typical k values: every set of k slots at the
        // per-validator cap passes; one extra atom on any slot trips the
        // per-validator branch first.
        for k in 1..=10 {
            let breakdown: Vec<_> = (0..k).map(|_| make_fee_share(3000)).collect();
            assert!(
                validate_fee_breakdown(1_000_000, &breakdown).is_ok(),
                "k={} at per-validator cap should pass", k,
            );
            let mut over = breakdown.clone();
            over[0] = make_fee_share(3001);
            assert_eq!(
                validate_fee_breakdown(1_000_000, &over),
                Err(ValidationError::FeeExceedsValidatorCap),
                "k={} with one over-cap slot trips per-validator branch first", k,
            );
        }
    }

    #[test]
    fn fee_breakdown_full_supply_amount_caps_apply() {
        // AXIOM total supply is 100M AXC = 10^18 atoms. At that amount the
        // u64 multiplications inside the cap math would overflow without the
        // u128 intermediates — verify the caps still apply correctly.
        // 10^18 * 30 / 10_000 = 3 * 10^15 atoms per-validator cap.
        let total_supply: u64 = 1_000_000_000_000_000_000;
        let per_val_cap: u64 = 3_000_000_000_000_000; // 3e15
        assert!(validate_fee_breakdown(total_supply, &[make_fee_share(per_val_cap)]).is_ok());
        assert_eq!(
            validate_fee_breakdown(total_supply, &[make_fee_share(per_val_cap + 1)]),
            Err(ValidationError::FeeExceedsValidatorCap),
        );
    }

    #[test]
    fn fee_breakdown_summed_overflow_caught_at_aggregate() {
        // Two slots each at u64::MAX/2 would NOT overflow u64 sum, but the
        // total far exceeds 90 bps of a small amount. u128 sum catches both
        // overflow and excess in one branch.
        let big = u64::MAX / 2;
        let breakdown = vec![make_fee_share(big), make_fee_share(big)];
        assert_eq!(
            validate_fee_breakdown(1_000_000, &breakdown),
            Err(ValidationError::FeeExceedsValidatorCap),
        );
    }

    #[test]
    fn fee_breakdown_amount_zero_rejects_any_nonzero_slot() {
        // amount = 0 → per_validator_cap = 0, aggregate_cap = 0.
        // Any positive slot exceeds per-validator cap and short-circuits.
        let breakdown = vec![make_fee_share(1)];
        assert_eq!(
            validate_fee_breakdown(0, &breakdown),
            Err(ValidationError::FeeExceedsValidatorCap),
        );
    }

    #[test]
    fn fee_breakdown_zero_slot_amounts_pass() {
        // All-zero slots (degenerate but legal) — caps are zero, total is zero.
        let breakdown = vec![make_fee_share(0), make_fee_share(0), make_fee_share(0)];
        assert!(validate_fee_breakdown(0, &breakdown).is_ok());
        assert!(validate_fee_breakdown(1_000_000, &breakdown).is_ok());
    }

    // ───────────────────────────────────────────────────────────────────
    // ───────────────────────────────────────────────────────────────────
    // compute_deed_split — DEED pool 10% collection + proportional
    // validator split with deterministic atom-granular remainder.
    // See docs/AXIOM_DESIGN_DeedDistribution.md.
    // ───────────────────────────────────────────────────────────────────

    /// Constant used in tests so the cutoff math matches what real
    /// Nablas use in production. 2026-03-19 midnight UTC, same value
    /// as `crate::genesis_integrity::GENESIS_NEWS_ANCHOR`.
    const ANCHOR: u64 = 1_773_878_400;

    fn fb(slots: &[u64]) -> Vec<FeeShare> {
        slots.iter().enumerate().map(|(i, &amount)| FeeShare {
            validator_id: [(i as u8 + 1) * 0x11; 32],
            amount,
        }).collect()
    }

    #[test]
    fn deed_split_equal_slots_at_axc_scale_is_clean_10_90() {
        // 3 validators × 3 AXC slots = 9 AXC total. DEED takes 0.9 AXC,
        // each validator nets 2.7 AXC. Atom-perfect at AXC scale.
        let breakdown = fb(&[30_000_000_000, 30_000_000_000, 30_000_000_000]);
        let s = compute_deed_split(&breakdown, &[0xAA; 32], ANCHOR + 60, ANCHOR);
        assert_eq!(s.deed_atoms, 9_000_000_000);
        assert_eq!(s.net_per_slot, vec![27_000_000_000; 3]);
        assert_eq!(s.deed_atoms + s.net_per_slot.iter().sum::<u64>(), 90_000_000_000);
    }

    #[test]
    fn deed_split_still_collects_after_ten_years() {
        // RULED 2026-09-14: DEED is PERPETUAL. Until then this test asserted
        // deed_atoms == 0 one second past a 10-year cutoff; it now pins that
        // the same tick still pays 10 % to DEED. A reintroduced sunset fails it.
        let breakdown = fb(&[30_000_000_000, 30_000_000_000, 30_000_000_000]);
        let ten_years_on = ANCHOR + 10 * 365 * 24 * 60 * 60 + 1;
        let s = compute_deed_split(&breakdown, &[0xAA; 32], ten_years_on, ANCHOR);
        assert_eq!(s.deed_atoms, 9_000_000_000, "DEED must still collect after 10 years");
        assert_eq!(s.net_per_slot, vec![27_000_000_000; 3]);
    }

    #[test]
    fn deed_split_empty_and_zero_fee_breakdowns() {
        // Empty fee_breakdown (send / heal / pre-fee paths) → all zeros.
        let s = compute_deed_split(&[], &[0xAA; 32], ANCHOR + 60, ANCHOR);
        assert_eq!(s.deed_atoms, 0);
        assert!(s.net_per_slot.is_empty());
        // Non-empty but zero amounts (degenerate) → all zeros, k entries.
        let s = compute_deed_split(&fb(&[0, 0, 0]), &[0xAA; 32], ANCHOR + 60, ANCHOR);
        assert_eq!(s.deed_atoms, 0);
        assert_eq!(s.net_per_slot, vec![0, 0, 0]);
    }

    #[test]
    fn deed_split_atom_granular_remainder_distributes_and_conserves() {
        // Three 15-atom slots. total=45, deed=floor(45/10)=4, val_pool=41.
        // Proportional net_i = floor(15 * 41 / 45) = 13 each → sum = 39.
        // Remainder = 41 - 39 = 2 atoms → distributed via BLAKE3 seed.
        let breakdown = fb(&[15, 15, 15]);
        let s = compute_deed_split(&breakdown, &[0xAA; 32], ANCHOR + 60, ANCHOR);
        assert_eq!(s.deed_atoms, 4);
        assert_eq!(s.net_per_slot.iter().sum::<u64>(), 41);
        assert_eq!(s.deed_atoms + s.net_per_slot.iter().sum::<u64>(), 45);
        // Exactly two of the three slots got the +1; one stayed at 13.
        let bonuses = s.net_per_slot.iter().filter(|&&x| x == 14).count();
        let bases = s.net_per_slot.iter().filter(|&&x| x == 13).count();
        assert_eq!(bonuses, 2);
        assert_eq!(bases, 1);
    }

    #[test]
    fn deed_split_unequal_slots_split_proportionally() {
        // Validators with mixed rates: 30B, 20B, 10B atoms (3 AXC, 2 AXC, 1 AXC).
        // total = 60B, deed = 6B, val_pool = 54B.
        // Proportional: net_i = floor(slot_i * 54B / 60B) = slot_i * 0.9.
        let breakdown = fb(&[30_000_000_000, 20_000_000_000, 10_000_000_000]);
        let s = compute_deed_split(&breakdown, &[0xAA; 32], ANCHOR + 60, ANCHOR);
        assert_eq!(s.deed_atoms, 6_000_000_000);
        assert_eq!(s.net_per_slot, vec![27_000_000_000, 18_000_000_000, 9_000_000_000]);
        assert_eq!(s.deed_atoms + s.net_per_slot.iter().sum::<u64>(), 60_000_000_000);
    }

    #[test]
    fn deed_split_is_deterministic_across_mesh() {
        // Same inputs → same output, byte for byte. Two Nablas with the
        // same tx_hash + tick MUST converge on the same split.
        let breakdown = fb(&[17, 19, 23, 29, 31]);  // arbitrary prime-ish slots
        let s1 = compute_deed_split(&breakdown, &[0xC3; 32], ANCHOR + 1234, ANCHOR);
        let s2 = compute_deed_split(&breakdown, &[0xC3; 32], ANCHOR + 1234, ANCHOR);
        assert_eq!(s1, s2);
        // Different tx_hash → different remainder distribution (with
        // overwhelming probability).
        let s3 = compute_deed_split(&breakdown, &[0xD4; 32], ANCHOR + 1234, ANCHOR);
        // Same deed_atoms (depends only on total), but the per-slot
        // distribution may differ. Conservation still holds.
        assert_eq!(s1.deed_atoms, s3.deed_atoms);
        assert_eq!(s3.deed_atoms + s3.net_per_slot.iter().sum::<u64>(),
                   breakdown.iter().map(|s| s.amount).sum::<u64>());
    }

    #[test]
    fn deed_split_conserves_atoms_for_arbitrary_inputs() {
        // Property check: for every k in 1..=5 and slots permuting a
        // range, deed_atoms + sum(net_per_slot) == sum(fee_breakdown).
        // Covers the atom-granular and AXC-scale regimes; if conservation
        // ever breaks for any case, this catches it.
        let candidate_slots: &[&[u64]] = &[
            &[10],
            &[10, 10],
            &[10, 10, 10],
            &[1, 2, 3, 4, 5],
            &[7, 7, 7, 7, 7],
            &[10_000_000, 10_000_000, 10_000_000],
            &[u32::MAX as u64, u32::MAX as u64, u32::MAX as u64],
            &[1, 999_999_999, 1],   // wildly unequal — proportional must hold
        ];
        for (i, slots) in candidate_slots.iter().enumerate() {
            let breakdown = fb(slots);
            let total: u64 = breakdown.iter().map(|s| s.amount).sum();
            let mut tx_hash = [0u8; 32];
            tx_hash[0] = i as u8;
            let s = compute_deed_split(&breakdown, &tx_hash, ANCHOR + 60, ANCHOR);
            assert_eq!(
                s.deed_atoms + s.net_per_slot.iter().sum::<u64>(), total,
                "conservation broke for slots={:?}", slots,
            );
            assert_eq!(s.net_per_slot.len(), breakdown.len());
        }
    }

    // ───────────────────────────────────────────────────────────────────
    // receipt_commitment binds the skeleton only — fee_breakdown is not
    // bound into the commitment; each WitnessSig self-attests its own slot
    // via verify_slot_math at sign time. (verify_receipt_fee_breakdown, the
    // old receipt-vs-witness cross-check, was DELETED — KI#156 item 2.)
    // ───────────────────────────────────────────────────────────────────

    #[test]
    fn receipt_commitment_is_stable_across_calls() {
        let txid = [0xAA; 32];
        let sh = [0xBB; 32];
        let cmit = [0xDD; 32];
        let c1 = crate::crypto::compute_receipt_commitment(&txid, &sh, 1, &cmit, 1, false, None, None, None);
        let c2 = crate::crypto::compute_receipt_commitment(&txid, &sh, 1, &cmit, 1, false, None, None, None);
        assert_eq!(c1, c2);
    }

    #[test]
    fn receipt_commitment_differs_per_skeleton_field() {
        // Any skeleton-field change MUST produce a different commitment —
        // this is what k validators' Ed25519 sigs cover.
        let base = crate::crypto::compute_receipt_commitment(
            &[0xAA; 32], &[0xBB; 32], 1, &[0xDD; 32], 1,
        false, None, None, None,
        );
        let dtxid = crate::crypto::compute_receipt_commitment(
            &[0xA1; 32], &[0xBB; 32], 1, &[0xDD; 32], 1,
        false, None, None, None,
        );
        let dsh   = crate::crypto::compute_receipt_commitment(
            &[0xAA; 32], &[0xB1; 32], 1, &[0xDD; 32], 1,
        false, None, None, None,
        );
        let dseq  = crate::crypto::compute_receipt_commitment(
            &[0xAA; 32], &[0xBB; 32], 2, &[0xDD; 32], 1,
        false, None, None, None,
        );
        let dcmit = crate::crypto::compute_receipt_commitment(
            &[0xAA; 32], &[0xBB; 32], 1, &[0xD1; 32], 1,
        false, None, None, None,
        );
        let depoch = crate::crypto::compute_receipt_commitment(
            &[0xAA; 32], &[0xBB; 32], 1, &[0xDD; 32], 2,
        false, None, None, None,
        );
        for c in [dtxid, dsh, dseq, dcmit, depoch] {
            assert_ne!(c, base, "any skeleton-field change must change the commitment");
        }
    }

    // ───────────────────────────────────────────────────────────────────
    // YP §19.6 — compute_earnings_attestation_payload (Step 6 wire signing)
    // ───────────────────────────────────────────────────────────────────

    fn ent(b: u8, amt: u64, tick: u64) -> crate::wire_client::EarningsEntry {
        let mut h = [0u8; 32];
        h[0] = b;
        crate::wire_client::EarningsEntry {
            tx_hash: h,
            amount: amt,
            tick,
            // Empty breakdown for the Step 6 tests — they exercise
            // the basic hash sensitivity, not §20.10 logic.
            full_fee_breakdown: Vec::new(),
        }
    }

    #[test]
    fn earnings_attestation_payload_deterministic() {
        let nid = [0x01; 32];
        let vid = [0x02; 32];
        let entries = vec![ent(0xAA, 100, 5), ent(0xBB, 200, 10)];
        let a = crate::crypto::compute_earnings_attestation_payload(
            &nid, &vid, 0, 100, 300, &entries, true, 0,
        );
        let b = crate::crypto::compute_earnings_attestation_payload(
            &nid, &vid, 0, 100, 300, &entries, true, 0,
        );
        assert_eq!(a, b);
    }

    #[test]
    fn earnings_attestation_payload_sensitive_to_every_field() {
        let nid = [0x01; 32];
        let vid = [0x02; 32];
        let entries = vec![ent(0xAA, 100, 5)];
        let base = crate::crypto::compute_earnings_attestation_payload(
            &nid, &vid, 0, 100, 100, &entries, true, 0,
        );

        // node_id shift
        let mut nid2 = nid; nid2[0] = 0x99;
        assert_ne!(base, crate::crypto::compute_earnings_attestation_payload(
            &nid2, &vid, 0, 100, 100, &entries, true, 0,
        ));

        // validator_id shift
        let mut vid2 = vid; vid2[0] = 0x99;
        assert_ne!(base, crate::crypto::compute_earnings_attestation_payload(
            &nid, &vid2, 0, 100, 100, &entries, true, 0,
        ));

        // since_tick
        assert_ne!(base, crate::crypto::compute_earnings_attestation_payload(
            &nid, &vid, 1, 100, 100, &entries, true, 0,
        ));

        // until_tick
        assert_ne!(base, crate::crypto::compute_earnings_attestation_payload(
            &nid, &vid, 0, 101, 100, &entries, true, 0,
        ));

        // total_amount
        assert_ne!(base, crate::crypto::compute_earnings_attestation_payload(
            &nid, &vid, 0, 100, 101, &entries, true, 0,
        ));

        // is_authoritative flip
        assert_ne!(base, crate::crypto::compute_earnings_attestation_payload(
            &nid, &vid, 0, 100, 100, &entries, false, 0,
        ));

        // entry amount shift
        let mut entries2 = entries.clone();
        entries2[0].amount += 1;
        assert_ne!(base, crate::crypto::compute_earnings_attestation_payload(
            &nid, &vid, 0, 100, 100, &entries2, true, 0,
        ));

        // entry tick shift
        let mut entries3 = entries.clone();
        entries3[0].tick += 1;
        assert_ne!(base, crate::crypto::compute_earnings_attestation_payload(
            &nid, &vid, 0, 100, 100, &entries3, true, 0,
        ));

        // Step 8.3.A — full_fee_breakdown shift detected.
        let mut entries4 = entries.clone();
        entries4[0].full_fee_breakdown = vec![
            FeeShare { validator_id: [0xCC; 32], amount: 999 },
        ];
        assert_ne!(base, crate::crypto::compute_earnings_attestation_payload(
            &nid, &vid, 0, 100, 100, &entries4, true, 0,
        ));
    }

    #[test]
    fn earnings_attestation_payload_sensitive_to_entry_order() {
        // SDK/SMT MUST produce a deterministic ordering; the hash is
        // order-sensitive so two honest nodes producing the same ordered
        // list get the same hash, and any reordering attempt is detectable.
        let nid = [0x01; 32];
        let vid = [0x02; 32];
        let a = vec![ent(0xAA, 100, 5), ent(0xBB, 200, 10)];
        let b = vec![ent(0xBB, 200, 10), ent(0xAA, 100, 5)];
        let h_a = crate::crypto::compute_earnings_attestation_payload(
            &nid, &vid, 0, 100, 300, &a, true, 0,
        );
        let h_b = crate::crypto::compute_earnings_attestation_payload(
            &nid, &vid, 0, 100, 300, &b, true, 0,
        );
        assert_ne!(h_a, h_b);
    }


    // KI#156 item 4 (DELETED 2026-09-21): `claim_payload_binds_tick_and_validator_id`
    // and its `vid`/`fs` helpers were removed with `compute_validator_claim_payload`
    // (0 production callers — the RETIRED MarkValidatorEarnings withdrawal chain).

    /// Step 7 end-to-end: K3Receipt::from_witness_values_with_fees
    /// produces bytes such that Nabla's chain-verify path (recompute
    /// receipt_commitment over the extension fields + verify k Ed25519
    /// sigs) passes. The SDK and Nabla independently compute the same
    /// hash — no shared state required.
    #[test]
    fn k3receipt_with_fees_produces_chain_verifiable_receipt() {
        use ed25519_dalek::{SigningKey, Signer, Verifier};
        use crate::types::FeeShare;

        // Pinned receipt-commitment inputs (SDK side knows these from CL3).
        let tx_hash = [0xAA; 32];
        let state_hash = [0xBB; 32];
        let produced_state_id = [0xCC; 32];
        let new_wallet_seq = 7u64;
        let commitment_hash = [0xDD; 32];
        let epoch = 1_700_000_000u64;
        let amount = 1_000_000u64;
        let cap = (amount * 30) / 10_000;

        let breakdown = vec![
            FeeShare { validator_id: [0x11; 32], amount: cap },
            FeeShare { validator_id: [0x22; 32], amount: cap },
            FeeShare { validator_id: [0x33; 32], amount: cap },
        ];

        let expected_commitment = crate::crypto::compute_receipt_commitment(
            &tx_hash, &state_hash, new_wallet_seq,
            &commitment_hash, epoch,
        false, None, None, None,
    );

        // Three "Lambdas" sign that commitment (mirroring Step 2's per-slot
        // sign — each Lambda calls verify_my_fee_slot then sign_receipt_commitment).
        let lambdas: Vec<(SigningKey, [u8; 32])> = (0..3).map(|i| {
            let sk = SigningKey::from_bytes(&[i as u8 + 1; 32]);
            let pk = sk.verifying_key().to_bytes();
            (sk, pk)
        }).collect();

        // Build witness CBOR each Lambda would emit — carries the
        // receipt_commitment_sig that Nabla will verify.
        use ciborium::Value;
        let witness_values: Vec<Value> = lambdas.iter().map(|(sk, pk)| {
            let sig = sk.sign(&expected_commitment);
            Value::Map(vec![
                (Value::Text("validator_pk".into()),
                 Value::Bytes(pk.to_vec())),
                (Value::Text("receipt_signature".into()),
                 Value::Bytes(vec![0u8; 64])), // not used by chain verify
                (Value::Text("receipt_commitment_sig".into()),
                 Value::Bytes(sig.to_bytes().to_vec())),
                (Value::Text("execution_proof".into()),
                 Value::Bytes(vec![])),
                (Value::Text("proof_type".into()),
                 Value::Integer(0.into())),
            ])
        }).collect();

        // SDK builds K3Receipt with full fee-aware shape.
        let receipt = crate::nabla_wire::K3Receipt::from_witness_values_with_fees(
            &[0u8; 32], &produced_state_id, &witness_values,
            amount, state_hash, new_wallet_seq, commitment_hash, epoch,
            breakdown.clone(),
        );

        // Recompute commitment over the receipt's stored fields — must match.
        let recomputed = crate::crypto::compute_receipt_commitment(
            &tx_hash,
            &receipt.state_hash,
            receipt.new_wallet_seq,
            &receipt.commitment_hash,
            receipt.epoch,
        false, None, None, None,
    );
        assert_eq!(recomputed, expected_commitment,
            "K3Receipt fields must reproduce the canonical commitment");

        // Every per-slot receipt_commitment_sig verifies against
        // recomputed commitment + the validator_pk on file.
        for ws in &receipt.signatures {
            assert_eq!(ws.receipt_commitment_sig.len(), 64,
                "from_witness_values_with_fees must populate receipt_commitment_sig");
            use ed25519_dalek::{Signature, VerifyingKey};
            let vk = VerifyingKey::from_bytes(&ws.validator_pk).unwrap();
            let sig_bytes: [u8; 64] = ws.receipt_commitment_sig.as_slice()
                .try_into().unwrap();
            let sig = Signature::from_bytes(&sig_bytes);
            vk.verify(&recomputed, &sig)
                .expect("each Lambda's receipt_commitment_sig must verify");
        }
    }

    /// YP §19.6 Step 8.2 — CL5 conservation invariant. The arithmetic
    /// inside `execute_cl5` is:
    ///   total_fee     = sum(fee_breakdown[i].amount)
    ///   net_to_receiver = effective_amount.saturating_sub(total_fee)
    ///   expected_new_balance = current_balance + net_to_receiver
    ///
    /// Cap rules (Step 1) guarantee total_fee ≤ effective_amount, so
    /// the subtraction never underflows. This test pins the formula's
    /// conservation property without spinning up a full ChequeBundle —
    /// Step 8.5 layers the integration test that exercises execute_cl5
    /// end-to-end.
    #[test]
    fn cl5_balance_math_preserves_conservation_under_fees() {
        // 3 validators × 30 bps cap = 90 bps total — aggregate cap.
        let amount: u64 = 1_000_000;
        let cap = (amount * 30) / 10_000;
        let breakdown = vec![
            FeeShare { validator_id: [0x11; 32], amount: cap },
            FeeShare { validator_id: [0x22; 32], amount: cap },
            FeeShare { validator_id: [0x33; 32], amount: cap },
        ];
        // Sanity: caps OK.
        assert!(validate_fee_breakdown(amount, &breakdown).is_ok());

        let total_fee: u64 = breakdown.iter().map(|s| s.amount).sum();
        let net_to_receiver = amount.saturating_sub(total_fee);

        // (1) Conservation: gross = net + fees. Nothing is minted or lost.
        assert_eq!(net_to_receiver + total_fee, amount);
        // (2) At the aggregate cap, net is exactly 99.10% of gross.
        assert_eq!(net_to_receiver, 991_000);
        assert_eq!(total_fee, 9_000);
    }

    #[test]
    fn cl5_balance_math_empty_breakdown_is_byte_identical_to_pre_step_8() {
        // Every today/pre-step-7 redeem carries empty fee_breakdown.
        // total_fee = 0, net = effective_amount — same as the original
        // CL5 expected_new_balance = current_balance + effective_amount.
        let amount: u64 = 1_000_000;
        let breakdown: Vec<FeeShare> = Vec::new();
        let total_fee: u64 = breakdown.iter().map(|s| s.amount).sum();
        let net_to_receiver = amount.saturating_sub(total_fee);
        assert_eq!(net_to_receiver, amount);
        assert_eq!(total_fee, 0);
    }

    #[test]
    fn cl5_balance_math_full_aggregate_cap_doesnt_drain_amount() {
        // Even at the aggregate cap, receiver retains 99.10%. Sanity
        // check that no edge case lets validators capture more than
        // the cap.
        let amount: u64 = 1_000_000;
        let max_total_fee = (amount * MAX_TOTAL_TX_FEE_BPS as u64) / FEE_BPS_DIVISOR;
        let net = amount.saturating_sub(max_total_fee);
        assert_eq!(max_total_fee, 9_000);
        assert_eq!(net, 991_000);
        assert!(net * 100 / amount >= 99);
    }

    #[test]
    fn earnings_attestation_payload_empty_entries_is_stable() {
        // Bloom-mode responses are empty + non-authoritative — must still
        // produce a determinate, signable hash.
        let nid = [0x01; 32];
        let vid = [0x02; 32];
        let a = crate::crypto::compute_earnings_attestation_payload(
            &nid, &vid, 0, 100, 0, &[], false, 0,
        );
        let b = crate::crypto::compute_earnings_attestation_payload(
            &nid, &vid, 0, 100, 0, &[], false, 0,
        );
        assert_eq!(a, b);
    }

    // ──────────────────────────────────────────────────────────────────────
    // §15 anchor check (verify_state_anchored) — CLAUDE.md §15
