    /// Helper: build a Receipt whose `state_hash` is the deterministic
    /// re-derivation from `(pk, balance, seq)` — i.e. an HONEST prev_receipt
    /// that any honest validator would have produced for that wallet state.
    fn make_anchor_test_receipt(pk: &[u8], balance: u64, seq: u64) -> Receipt {
        let state_hash = crate::crypto::compute_state_hash(pk, balance, seq, 0, 0, 0, 0, &crate::types::WalletFormat::CURRENT);
        Receipt {
            oods_flag: None,
            confidence_index: None,
            sender_state: None,
            txid: [0u8; 32],
            state_hash,
            produced_state_id: [0u8; 32],
            new_wallet_seq: seq,
            commitment_hash: [0u8; 32],
            sdid: [0u8; 32],
            lineage_hash: [0u8; 32],
            core_version: String::new(),
            core_id: [0u8; 32],
            witness_sigs: vec![],
            epoch: 0,
            fact_proof: None,
            required_k: 3,
            receipt_commitment: [0u8; 32],
            fee_breakdown: Vec::new(),
            is_dev_class: false,
        }
    }

